    #[test]
    fn scheduler_mail_selection_filters_ineligible_residency_before_role_ranking() {
        let (fixture, session, _source, target, context, mut request) = collaboration_fixture();
        let port = FakePort::new();
        let resident = Uuid::parse_str(
            &fixture
                .spawn_member(session, "resident-peer", &port)
                .member
                .member_ref,
        )
        .unwrap();
        collaboration_core(&fixture, resident, crate::domain::RunLifecycle::Idle, None);
        let db = rusqlite::Connection::open(fixture.database()).unwrap();
        db.execute(
            "UPDATE brokered_members SET actor_residency='passivated' WHERE run_id=?1",
            [target.to_string()],
        )
        .unwrap();
        request["target"] = json!({"role_ref":"reviewer"});
        let mut broker =
            crate::orchestration::OrchestrationStore::open(&fixture.state_root).unwrap();
        let mut effects = crate::semantic::ProductionOrchestrationEffects::new(&fixture.state_root);
        assert_eq!(
            crate::collaboration::admit(&mut broker, &context, &request, &mut effects).unwrap()["target_run_id"],
            resident.to_string()
        );
        // On-mail targets remain eligible while the durable activation or stop
        // owner is working. Additional mail must not create another generation.
        for residency in ["activating", "passivating"] {
            let mut policy = managed_policy();
            policy.roles[0].collaboration_source = true;
            policy.roles[0].collaboration_target = true;
            policy.roles[0].activation_policy = "on_mail".into();
            let (fixture, session, _source, target, context, request) =
                collaboration_fixture_policy(policy);
            let db = rusqlite::Connection::open(fixture.database()).unwrap();
            db.execute(
                "UPDATE brokered_members SET actor_residency=?2 WHERE run_id=?1",
                rusqlite::params![target.to_string(), residency],
            )
            .unwrap();
            let mut broker =
                crate::orchestration::OrchestrationStore::open(&fixture.state_root).unwrap();
            let mut effects =
                crate::semantic::ProductionOrchestrationEffects::new(&fixture.state_root);
            assert_eq!(
                crate::collaboration::admit(&mut broker, &context, &request, &mut effects).unwrap()
                    ["target_run_id"],
                target.to_string(),
                "{session} {residency}"
            );
        }
    }

    #[test]
    fn scheduler_consultation_effect_uses_original_deadline_and_lifecycle_cap() {
        let (fixture, session, _, target, context, request) = collaboration_fixture();
        let mut broker =
            crate::orchestration::OrchestrationStore::open(&fixture.state_root).unwrap();
        let mut effects = crate::semantic::ProductionOrchestrationEffects::new(&fixture.state_root);
        let admitted =
            crate::collaboration::admit(&mut broker, &context, &request, &mut effects).unwrap();
        let exchange = Uuid::parse_str(admitted["exchange_id"].as_str().unwrap()).unwrap();
        let owner = crate::assignment_queue::Owner::Managed(session);
        let actor = crate::scheduler::Actor { owner, run: target };
        let mut store = EngagementStore::open(&fixture.database()).unwrap();
        let now = now_ms().unwrap();
        let permit = store
            .transact(|tx| {
                crate::scheduler::observe_actor(tx, actor, 1, true, now)?;
                crate::scheduler::claim(tx, owner, target, now)
            })
            .unwrap()
            .unwrap();
        assert_eq!(permit.work, exchange);
        let original = crate::collaboration::execution_record(store.connection(), exchange)
            .unwrap()
            .deadline_ms;
        store
            .transact(|tx| {
                crate::scheduler::prepare_dispatch(tx, &permit, now)?;
                tx.execute(
                    "UPDATE scheduler_claims SET lease_until_ms=0 WHERE claim_id=?1",
                    [permit.claim.to_string()],
                )
                .unwrap();
                Ok(())
            })
            .unwrap();
        let record = crate::collaboration::execution_record(store.connection(), exchange).unwrap();
        assert!(
            crate::collaboration::bind_execution(
                &fixture.state_root,
                session,
                target,
                &format!("collaboration-exchange:{exchange}"),
                false,
                &record.prompt
            )
            .unwrap()
        );
        let before_budget = now_ms().unwrap();
        let remaining = crate::scheduler::effect_remaining(&fixture.state_root, target)
            .unwrap()
            .unwrap();
        assert!(remaining > std::time::Duration::from_secs(30));
        assert!(remaining <= std::time::Duration::from_millis((original - before_budget) as u64));
        assert_eq!(
            crate::collaboration::execution_record(store.connection(), exchange)
                .unwrap()
                .deadline_ms,
            original
        );
        assert!(
            store
                .transact(|tx| crate::scheduler::claim(tx, owner, target, now_ms()?))
                .unwrap()
                .is_none()
        );
        for kind in ["activation", "passivation"] {
            store.transact(|tx| {
                tx.execute("UPDATE scheduler_actors SET operation_id=?2,operation_kind=?3,lease_until_ms=?4 WHERE target_run_id=?1", rusqlite::params![target.to_string(),Uuid::now_v7().to_string(),kind,now_ms()?+1_000]).unwrap();
                Ok(())
            }).unwrap();
            assert!(
                crate::scheduler::effect_remaining(&fixture.state_root, target)
                    .unwrap()
                    .unwrap()
                    <= std::time::Duration::from_secs(1)
            );
        }
    }

    #[test]
    fn scheduler_expires_original_assignment_deadlines_once_without_dispatch() {
        for (managed, full_quota) in [(false, false), (true, false), (false, true), (true, true)] {
            let fixture = Fixture::new();
            let port = FakePort::new();
            let (scope, member, owner) = if managed {
                let scope = fixture.managed_session();
                let member = Uuid::parse_str(
                    &fixture
                        .spawn_member(scope, "expiry-spawn", &port)
                        .member
                        .member_ref,
                )
                .unwrap();
                (
                    scope,
                    member,
                    crate::assignment_queue::Owner::Managed(scope),
                )
            } else {
                fixture.set_up_namespace();
                let scope = fixture.open();
                let candidate = fixture.install();
                (
                    scope,
                    fixture.hire_member(scope, &candidate, "expiry-hire"),
                    crate::assignment_queue::Owner::External(scope),
                )
            };
            let mut receipts = Vec::new();
            for (key, seconds) in [("expiry-first", 1), ("expiry-later", 600)] {
                let result = if managed {
                    let mut request =
                        managed_assign(member, "Retained expiry body.", "read_only", None);
                    request.deadline_seconds = seconds;
                    queue_specialist_task(
                        &fixture.scope(),
                        &fixture.managed_context(scope, key),
                        &caller(16),
                        &port,
                        request,
                        1,
                    )
                    .unwrap()
                } else {
                    let mut request = assign_request(scope, member, key, "read_only");
                    request.deadline_seconds = seconds;
                    queue_external_specialist_task(&fixture.scope(), &caller(16), &port, request, 1)
                        .unwrap()
                };
                receipts.push(result.1);
            }
            let task = Uuid::parse_str(receipts[0].accepted_subjects.task_ref.as_deref().unwrap())
                .unwrap();
            let later = receipts[1].accepted_subjects.task_ref.as_ref().unwrap();
            let actor = crate::scheduler::Actor { owner, run: member };
            if managed {
                fixture.publish_member_manifest(scope, member);
            } else {
                fixture.publish_external_member_manifest(scope, member);
            }
            let directory = fixture
                .state_root
                .join("runs")
                .join(member.to_string())
                .join("artifacts");
            fs::create_dir_all(&directory).unwrap();
            fs::set_permissions(&directory, fs::Permissions::from_mode(0o700)).unwrap();
            if full_quota {
                use std::os::unix::fs::OpenOptionsExt;
                for _ in 0..8 {
                    let file = fs::OpenOptions::new()
                        .create_new(true)
                        .write(true)
                        .mode(0o600)
                        .open(directory.join(format!("{}.bin", Uuid::now_v7())))
                        .unwrap();
                    file.set_len(32 * 1024 * 1024).unwrap();
                }
                assert_eq!(
                    crate::artifact::logical_artifact_bytes(&directory).unwrap(),
                    crate::artifact::MAX_RUN_ARTIFACT_BYTES
                );
            }
            let store = EngagementStore::open(&fixture.database()).unwrap();
            let deadline: i64 = store
                .connection()
                .query_row(
                    "SELECT deadline_ms FROM assignment_queue_entries WHERE task_id=?1",
                    [task.to_string()],
                    |r| r.get(0),
                )
                .unwrap();
            crate::semantic::expire_queued_tasks(
                &fixture.view,
                &fixture.state_root,
                actor,
                deadline - 1,
            )
            .unwrap();
            assert_eq!(
                crate::scheduler::candidates(store.connection(), owner, member)
                    .unwrap()
                    .len(),
                2
            );
            crate::semantic::fail_next_queued_expiry_publication();
            assert!(
                crate::semantic::expire_queued_tasks(
                    &fixture.view,
                    &fixture.state_root,
                    actor,
                    deadline
                )
                .is_err()
            );
            assert_eq!(
                crate::scheduler::candidates(store.connection(), owner, member)
                    .unwrap()
                    .len(),
                2,
                "failed publication rolls back the terminal transition"
            );
            assert!(
                crate::engagement::result_component_records(
                    store.connection(),
                    "result-component-"
                )
                .unwrap()
                .is_empty(),
                "binding rollback leaves no result or artifact identities"
            );
            crate::semantic::expire_queued_tasks(
                &fixture.view,
                &fixture.state_root,
                actor,
                deadline,
            )
            .unwrap();
            let records = crate::engagement::result_component_records(
                store.connection(),
                "result-component-",
            )
            .unwrap();
            crate::semantic::expire_queued_tasks(
                &fixture.view,
                &fixture.state_root,
                actor,
                deadline,
            )
            .unwrap();
            assert_eq!(
                crate::engagement::result_component_records(
                    store.connection(),
                    "result-component-"
                )
                .unwrap(),
                records,
                "expiry replay preserves every original result/artifact identity"
            );
            let query = if managed {
                "SELECT state,safe_error_code,target_turn_id FROM brokered_tasks WHERE task_id=?1"
            } else {
                "SELECT state,safe_error_code,turn_id FROM tasks WHERE task_id=?1"
            };
            let state: (String, String, Option<String>) = store
                .connection()
                .query_row(query, [task.to_string()], |r| {
                    Ok((r.get(0)?, r.get(1)?, r.get(2)?))
                })
                .unwrap();
            assert_eq!(state, ("expired".into(), "OPERATION_TIMEOUT".into(), None));
            let (_, _, identity) = complete_result_of(
                &store,
                if managed {
                    SettlementOwner::Managed { session_id: scope }
                } else {
                    SettlementOwner::External {
                        engagement_id: scope,
                    }
                },
                member,
                task,
                &crate::scheduler::retained_assignment(
                    store.connection(),
                    owner,
                    task,
                    member,
                    &fixture.view.workspace_id,
                    &fixture.state_root,
                )
                .unwrap()
                .accepted
                .digest()
                .unwrap(),
                "expired",
                "collect_group",
            )
            .unwrap()
            .unwrap();
            assert_eq!(identity.terminal_outcome, "expired");
            let public = crate::result_component_artifact::public_result(
                &fixture.state_root,
                &fixture.view,
                &identity,
            )
            .unwrap();
            assert_eq!(
                Uuid::parse_str(public["result_id"].as_str().unwrap())
                    .unwrap()
                    .get_version_num(),
                7
            );
            assert_eq!(public["identity"]["safe_failure_code"], "OPERATION_TIMEOUT");
            assert_eq!(public["final_response"], Value::Null);
            assert_eq!(public["source_manifest"].is_null(), full_quota);
            if full_quota {
                assert_eq!(
                    public["discovery_unavailable_reason"],
                    "artifact_capacity_exceeded"
                );
                assert_eq!(
                    crate::artifact::logical_artifact_bytes(&directory).unwrap(),
                    crate::artifact::MAX_RUN_ARTIFACT_BYTES
                );
            }
            assert_eq!(store.connection().query_row("SELECT accounting_state FROM caller_scope_assignments WHERE assignment_id=?1",[task.to_string()],|r|r.get::<_,String>(0)).unwrap(),"proved_nondispatch");
            assert_eq!(
                store
                    .connection()
                    .query_row(
                        "SELECT COUNT(*) FROM assignment_queue_entries WHERE task_id=?1",
                        [task.to_string()],
                        |r| r.get::<_, u64>(0)
                    )
                    .unwrap(),
                0
            );
            let remaining =
                crate::scheduler::candidates(store.connection(), owner, member).unwrap();
            assert_eq!(remaining.len(), 1);
            assert_eq!(remaining[0].id.to_string(), *later);
            let query = if managed {
                "SELECT COUNT(*) FROM orchestration_events WHERE session_id=?1 AND kind='scheduler_queued_work_expired'"
            } else {
                "SELECT COUNT(*) FROM events WHERE engagement_id=?1 AND kind='scheduler_queued_work_expired'"
            };
            assert_eq!(
                store
                    .connection()
                    .query_row(query, [scope.to_string()], |r| r.get::<_, u64>(0))
                    .unwrap(),
                1
            );
            assert!(
                matches!(store.intent_lookup(&receipts[0].namespace).unwrap(),engagement::IntentLookup::Accepted(ref retained) if retained.as_ref()==&receipts[0])
            );
            assert!(port.dispatched_tasks().is_empty());
        }
    }

    #[test]
    fn scheduler_expires_collaboration_consultation_without_dispatch_or_duplicate_event() {
        let (fixture, session, source, target, mut context, request) = collaboration_fixture();
        let mut broker =
            crate::orchestration::OrchestrationStore::open(&fixture.state_root).unwrap();
        let mut effects = crate::semantic::ProductionOrchestrationEffects::new(&fixture.state_root);
        let admitted =
            crate::collaboration::admit(&mut broker, &context, &request, &mut effects).unwrap();
        let id = Uuid::parse_str(admitted["exchange_id"].as_str().unwrap()).unwrap();
        let actor = crate::scheduler::Actor {
            owner: crate::assignment_queue::Owner::Managed(session),
            run: target,
        };
        let mut store = EngagementStore::open(&fixture.database()).unwrap();
        let original = crate::collaboration::execution_record(store.connection(), id)
            .unwrap()
            .deadline_ms;
        let mail: u64 = store
            .connection()
            .query_row("SELECT COUNT(*) FROM collaboration_mailbox", [], |r| {
                r.get(0)
            })
            .unwrap();
        store
            .transact(|tx| crate::scheduler::expire_queued(tx, actor, original - 1))
            .unwrap();
        assert!(
            crate::scheduler::candidates(store.connection(), actor.owner, target)
                .unwrap()
                .iter()
                .any(|c| c.id == id)
        );
        for _ in 0..2 {
            store
                .transact(|tx| crate::scheduler::expire_queued(tx, actor, original))
                .unwrap();
        }
        assert_eq!(
            store
                .connection()
                .query_row(
                    "SELECT execution_state FROM collaboration_exchanges WHERE exchange_id=?1",
                    [id.to_string()],
                    |r| r.get::<_, String>(0)
                )
                .unwrap(),
            "expired"
        );
        assert!(
            crate::scheduler::candidates(store.connection(), actor.owner, target)
                .unwrap()
                .is_empty()
        );
        assert_eq!(
            store
                .connection()
                .query_row(
                    "SELECT COUNT(*) FROM scheduler_claims WHERE target_run_id=?1",
                    [target.to_string()],
                    |r| r.get::<_, u64>(0)
                )
                .unwrap(),
            0
        );
        assert_eq!(store.connection().query_row("SELECT COUNT(*) FROM orchestration_events WHERE session_id=?1 AND kind='scheduler_queued_work_expired'",[session.to_string()],|r|r.get::<_,u64>(0)).unwrap(),1);
        assert_eq!(
            store
                .connection()
                .query_row("SELECT COUNT(*) FROM collaboration_mailbox", [], |r| r
                    .get::<_, u64>(0))
                .unwrap(),
            mail
        );
        assert_eq!(
            store
                .connection()
                .query_row(
                    "SELECT deadline_ms FROM collaboration_exchanges WHERE exchange_id=?1",
                    [id.to_string()],
                    |r| r.get::<_, i64>(0)
                )
                .unwrap(),
            original
        );
        assert_eq!(
            store
                .connection()
                .query_row(
                    "SELECT count(*) FROM collaboration_result_outbox WHERE source_run_id=?1",
                    [source.to_string()],
                    |r| r.get::<_, u64>(0)
                )
                .unwrap(),
            1
        );
        assert_eq!(
            store
                .connection()
                .query_row(
                    "SELECT count(*) FROM collaboration_execution_links",
                    [],
                    |r| r.get::<_, u64>(0)
                )
                .unwrap(),
            0
        );
        assert_eq!(
            store
                .connection()
                .query_row(
                    "SELECT count(*) FROM orchestration_events WHERE kind='collaboration_expired'",
                    [],
                    |r| r.get::<_, u64>(0)
                )
                .unwrap(),
            1
        );
        context.source_tool_call_id = "collect-expired".into();
        let expired = collaboration_call(
            &fixture,
            &context,
            &json!({"operation":"collect_collaboration_results","limit":1}),
        )
        .unwrap();
        assert_eq!(expired["results"][0]["execution_state"], "expired");
        assert!(expired["results"][0]["result_artifact_ref"].is_null());
    }

    #[test]
    fn scheduler_retained_body_and_receipt_tampering_never_claim_new_authority() {
        for tamper in ["content", "receipt", "owner", "causal_order"] {
            let fixture = Fixture::new();
            fixture.set_up_namespace();
            let scope = fixture.open();
            let candidate = fixture.install();
            let member = fixture.hire_member(scope, &candidate, "authority-hire");
            let (_, receipt) = queue_external_specialist_task(
                &fixture.scope(),
                &caller(16),
                &FakePort::new(),
                assign_request(scope, member, "authority-queue", "read_only"),
                1,
            )
            .unwrap();
            let owner = crate::assignment_queue::Owner::External(scope);
            let mut store = EngagementStore::open(&fixture.database()).unwrap();
            let permit = store
                .transact(|tx| crate::scheduler::claim(tx, owner, member, now_ms()?))
                .unwrap()
                .unwrap();
            assert!(
                crate::scheduler::retained_task(
                    &store,
                    &permit,
                    &fixture.view.workspace_id,
                    &fixture.state_root
                )
                .is_ok()
            );
            store.transact(|tx|{
                match tamper {
                    "content"=>{tx.execute("UPDATE result_content SET bytes=x'7b7d' WHERE sha256 IN (SELECT sha256 FROM result_content_refs WHERE owner_kind='accepted_task' AND owner_id=?1 AND representation='task_body')",[permit.work.to_string()]).unwrap();},
                    "receipt"=>{
                    assert!(tx.execute("UPDATE delegation_operations SET receipt_json='{}' WHERE operation_ref=?1",[receipt.operation_ref.to_string()]).is_err());
                    // Simulate storage corruption only after proving the normal
                    // application update is rejected by the immutable guard.
                    tx.execute_batch("DROP TRIGGER delegation_receipt_frozen").unwrap();
                    tx.execute("UPDATE delegation_operations SET receipt_json='{}' WHERE operation_ref=?1",[receipt.operation_ref.to_string()]).unwrap();},
                    "owner"=>{tx.execute("UPDATE engagements SET controller_binding_json='{}' WHERE engagement_id=?1",[scope.to_string()]).unwrap();},
                    "causal_order"=>{tx.execute("DELETE FROM events WHERE engagement_id=?1 AND kind='assignment_queued'",[scope.to_string()]).unwrap();},
                    _=>unreachable!(),
                };Ok(())
            }).unwrap();
            let denied = if tamper == "causal_order" {
                crate::scheduler::candidates(store.connection(), owner, member).is_err()
            } else {
                crate::scheduler::retained_task(
                    &store,
                    &permit,
                    &fixture.view.workspace_id,
                    &fixture.state_root,
                )
                .is_err()
            };
            assert!(denied, "{tamper}");
            assert_eq!(
                store
                    .connection()
                    .query_row(
                        "SELECT state FROM tasks WHERE task_id=?1",
                        [permit.work.to_string()],
                        |r| r.get::<_, String>(0)
                    )
                    .unwrap(),
                "queued"
            );
        }
    }
    fn collaboration_captured_controller(fixture: &Fixture, member: Uuid) {
        let database = rusqlite::Connection::open(fixture.database()).unwrap();
        let captured: String = database
            .query_row(
                "SELECT controller_binding_json FROM brokered_members WHERE run_id=?1",
                [member.to_string()],
                |r| r.get(0),
            )
            .unwrap();
        let captured: ControllerBinding = serde_json::from_str(&captured).unwrap();
        let path = crate::run::run_root(&fixture.state_root, member).join("manifest.json");
        let mut manifest: crate::run::RunManifest =
            serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();
        let controller_path =
            crate::run::run_root(&fixture.state_root, member).join("controller.json");
        let controller: ControllerBinding =
            serde_json::from_slice(&fs::read(&controller_path).unwrap()).unwrap();
        if manifest.controller == captured && controller == captured {
            return;
        }
        assert_eq!(database.query_row("SELECT count(*) FROM collaboration_exchanges WHERE source_run_id=?1 OR target_run_id=?1",[member.to_string()],|r|r.get::<_,u64>(0)).unwrap(),0,"Controller setup must precede exchange admission");
        manifest.controller = captured.clone();
        fs::write(path, serde_json::to_vec(&manifest).unwrap()).unwrap();
        fs::write(controller_path, serde_json::to_vec(&captured).unwrap()).unwrap();
    }

    fn collaboration_observable_core(fixture: &Fixture, run: Uuid) {
        let directory = crate::run::run_root(&fixture.state_root, run);
        let path = directory.join("state.json");
        let mut state: crate::projection::RunStateProjection =
            serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();
        if state.ledger_head.sequence != 0 {
            return;
        }
        let payload = json!({"thread_id":"native-thread","thread_generation":1,"effective_policy":{"access":"read","verification":"unverified","policy_epoch":1,"thread_generation":1,"server_epoch":null,"writer_generation":null}});
        let record = crate::audit::AuditRecord::new(
            1,
            "2026-10-30T00:00:00.000000Z",
            run,
            1,
            crate::audit::AuditKind::ThreadBound,
            crate::jcs::parse(&payload.to_string()).unwrap(),
            crate::audit::GENESIS_PREVIOUS_HASH,
        )
        .unwrap();
        fs::write(
            directory.join("audit.jsonl"),
            record.canonical_line().unwrap(),
        )
        .unwrap();
        fs::set_permissions(
            directory.join("audit.jsonl"),
            fs::Permissions::from_mode(0o600),
        )
        .unwrap();
        state.ledger_head.sequence = 1;
        state.ledger_head.hash = record.hash().into();
        state.access = crate::domain::Access::Read;
        fs::write(path, serde_json::to_vec(&state).unwrap()).unwrap();
    }

    fn collaboration_call(
        fixture: &Fixture,
        ctx: &crate::orchestration::PrimaryCallContext,
        request: &Value,
    ) -> Result<Value, MachineError> {
        let mut store = crate::orchestration::OrchestrationStore::open(&fixture.state_root)?;
        let mut effects = crate::semantic::ProductionOrchestrationEffects::new(&fixture.state_root);
        crate::collaboration::admit(&mut store, ctx, request, &mut effects)
    }

    fn collaboration_accept(
        fixture: &Fixture,
        session: Uuid,
        source: Uuid,
        target: Uuid,
        ctx: &mut crate::orchestration::PrimaryCallContext,
        request: &Value,
        label: &str,
    ) -> (Uuid, crate::turn::TerminalTurn) {
        collaboration_captured_controller(fixture, source);
        collaboration_captured_controller(fixture, target);
        ctx.source_tool_call_id = label.into();
        let receipt = collaboration_call(fixture, ctx, request).unwrap();
        let id = Uuid::parse_str(receipt["exchange_id"].as_str().unwrap()).unwrap();
        let mut store = EngagementStore::open(&fixture.database()).unwrap();
        collaboration_observable_core(fixture, target);
        collaboration_observable_core(fixture, source);
        let snapshot = crate::snapshot::RunSnapshot::load(&fixture.state_root, target, 0).unwrap();
        let actor = crate::scheduler::Actor {
            owner: crate::assignment_queue::Owner::Managed(session),
            run: target,
        };
        store
            .transact(|tx| {
                crate::scheduler::reconcile_claim(
                    tx,
                    actor,
                    &snapshot,
                    now_ms()?,
                    &fixture.state_root,
                )?;
                let permit = crate::scheduler::claim(tx, actor.owner, target, now_ms()?)?.unwrap();
                assert_eq!(permit.work, id);
                crate::scheduler::prepare_dispatch(tx, &permit, now_ms()?)?;
                crate::collaboration::link_turn(tx, id, target, "native-thread", label, 1)?;
                crate::scheduler::finish_dispatch(
                    tx,
                    &permit,
                    &MemberDispatchOutcome::Accepted {
                        turn_ref: label.into(),
                    },
                    now_ms()?,
                )
            })
            .unwrap();
        assert_ne!(source, target);
        (
            id,
            crate::turn::TerminalTurn {
                thread_id: "native-thread".into(),
                turn_id: label.into(),
                status: "completed".into(),
                effort: "low".into(),
                final_response: Some(crate::turn::FinalResponse::Inline {
                    text: format!("Safe answer {label}: 한글."),
                }),
                usage: None,
            },
        )
    }

    #[test]
    fn collaboration_source_pages_bind_full_content_replay_and_utf8_progress() {
        let (fixture, session, source, target, mut ctx, request) = collaboration_fixture();
        fixture.initialize_writer_authority();
        let (exchange, mut terminal) = collaboration_accept(
            &fixture,
            session,
            source,
            target,
            &mut ctx,
            &request,
            "page-result",
        );
        ctx.source_tool_call_id = "page-not-ready".into();
        let pending = collaboration_call(
            &fixture,
            &ctx,
            &json!({
                "operation":"read_collaboration_result", "exchange_id":exchange,"offset":0,"limit":3
            }),
        )
        .unwrap_err();
        assert!(pending.retryable);
        let projected = crate::collaboration::error_result(&pending);
        assert_eq!(projected["code"], "COLLABORATION_TRANSPORT_UNAVAILABLE");
        assert_eq!(
            projected["message"],
            "The consultation result is not available yet."
        );
        let text = format!("한{}", "safe result ".repeat(7000));
        terminal.final_response = Some(crate::turn::FinalResponse::Inline { text: text.clone() });
        crate::collaboration::settle_target(&fixture.state_root, target, &terminal).unwrap();
        let request = |offset, limit| {
            json!({
                "operation":"read_collaboration_result","exchange_id":exchange,
                "offset":offset,"limit":limit
            })
        };
        ctx.source_tool_call_id = "page-first".into();
        let first = collaboration_call(&fixture, &ctx, &request(0, 3)).unwrap();
        assert_eq!(first["content"], "한");
        assert_eq!(first["length"], text.len());
        assert_eq!(first["sha256"], crate::jcs::sha256_hex(text.as_bytes()));
        assert_eq!(first["truncated"], true);
        assert_eq!(
            collaboration_call(&fixture, &ctx, &request(0, 3)).unwrap(),
            first
        );
        assert_eq!(
            collaboration_call(&fixture, &ctx, &request(3, 3))
                .unwrap_err()
                .code,
            "COLLABORATION_IDEMPOTENCY_CONFLICT"
        );
        let checked_db = rusqlite::Connection::open(fixture.database()).unwrap();
        let receipts_before: u64 = checked_db
            .query_row(
                "SELECT count(*) FROM collaboration_tool_receipts",
                [],
                |r| r.get(0),
            )
            .unwrap();
        for (n, offset, limit) in [
            (0, 1, 3),
            (1, 0, 1),
            (2, text.len() as u64 + 1, 3),
            (3, 0, 0),
            (4, 0, 65_537),
        ] {
            ctx.source_tool_call_id = format!("page-invalid-{n}");
            let refused = collaboration_call(&fixture, &ctx, &request(offset, limit)).unwrap_err();
            assert_eq!(refused.code, "COLLABORATION_NOT_ALLOWED");
            assert!(!refused.retryable);
            assert_eq!(
                checked_db
                    .query_row(
                        "SELECT count(*) FROM collaboration_tool_receipts",
                        [],
                        |r| r.get::<_, u64>(0)
                    )
                    .unwrap(),
                receipts_before
            );
        }
        ctx.source_tool_call_id = "page-eof".into();
        let eof = collaboration_call(&fixture, &ctx, &request(text.len() as u64, 1)).unwrap();
        assert_eq!(eof["content"], "");
        assert_eq!(eof["truncated"], false);
        let mut offset = 0;
        let mut rebuilt = String::new();
        loop {
            ctx.source_tool_call_id = format!("page-{offset}");
            let page = collaboration_call(&fixture, &ctx, &request(offset, 65_536)).unwrap();
            let body = page["content"].as_str().unwrap();
            rebuilt.push_str(body);
            offset += body.len() as u64;
            if page["truncated"] == false {
                break;
            }
            assert!(!body.is_empty());
        }
        assert_eq!(rebuilt, text);
        let foreign_ctx = collaboration_prepare_source(
            &fixture,
            session,
            target,
            &FakePort::new(),
            "foreign-page-root",
            "foreign-page-turn",
        );
        assert_eq!(
            collaboration_call(&fixture, &foreign_ctx, &request(0, 3))
                .unwrap_err()
                .code,
            "COLLABORATION_NOT_ALLOWED",
        );
        // Each call reopens the owner store, so exact replay is restart-independent.
        ctx.source_tool_call_id = "page-first".into();
        assert_eq!(
            collaboration_call(&fixture, &ctx, &request(0, 3)).unwrap(),
            first
        );
        let c = rusqlite::Connection::open(fixture.database()).unwrap();
        let before: u64 = c
            .query_row(
                "SELECT count(*) FROM collaboration_tool_receipts",
                [],
                |r| r.get(0),
            )
            .unwrap();
        let foreign = json!({"operation":"read_collaboration_result","exchange_id":Uuid::now_v7(),"offset":0,"limit":3});
        ctx.source_tool_call_id = "foreign-page".into();
        assert_eq!(
            collaboration_call(&fixture, &ctx, &foreign)
                .unwrap_err()
                .code,
            "COLLABORATION_NOT_ALLOWED"
        );
        assert_eq!(
            c.query_row(
                "SELECT count(*) FROM collaboration_tool_receipts",
                [],
                |r| r.get::<_, u64>(0)
            )
            .unwrap(),
            before
        );
        let digest = first["sha256"].as_str().unwrap();
        c.execute(
            "UPDATE result_content SET bytes=?1 WHERE sha256=?2",
            rusqlite::params![b"changed".as_slice(), digest],
        )
        .unwrap();
        ctx.source_tool_call_id = "page-first".into();
        let failure = collaboration_call(&fixture, &ctx, &request(0, 3)).unwrap_err();
        assert_eq!(failure.code, "COLLABORATION_TRANSPORT_UNAVAILABLE");
        assert!(!failure.retryable);
    }

    #[test]
    fn checked_state_rejects_actual_result_body_motion_after_full_validation() {
        struct ChangeBody {
            database: PathBuf,
            reached: std::sync::atomic::AtomicBool,
        }
        impl crate::orchestration::OrchestrationFaultInjector for ChangeBody {
            fn check(
                &self,
                barrier: crate::orchestration::OrchestrationBarrier,
            ) -> Result<(), MachineError> {
                if barrier
                    == crate::orchestration::OrchestrationBarrier::AfterCheckedStatePreparation
                    && !self.reached.swap(true, std::sync::atomic::Ordering::SeqCst)
                {
                    let c = rusqlite::Connection::open(&self.database).unwrap();
                    assert_eq!(c.execute("UPDATE result_content SET bytes=zeroblob(length(bytes)) WHERE sha256 IN (SELECT sha256 FROM result_content_refs WHERE owner_kind='collaboration_result')",[]).unwrap(),1);
                }
                Ok(())
            }
        }
        let (fixture, session, source, target, mut ctx, request) = collaboration_fixture();
        fixture.initialize_writer_authority();
        let (_, terminal) = collaboration_accept(
            &fixture,
            session,
            source,
            target,
            &mut ctx,
            &request,
            "state-body-motion",
        );
        crate::collaboration::settle_target(&fixture.state_root, target, &terminal).unwrap();
        let mut owner =
            crate::orchestration::OrchestrationStore::open(&fixture.state_root).unwrap();
        owner
            .refresh_checked_state(&fixture.view.workspace_id)
            .unwrap();
        let path = fixture.state_root.join("orchestration/state.json");
        let before = fs::read(&path).unwrap();
        drop(owner);
        let fault = std::sync::Arc::new(ChangeBody {
            database: fixture.database(),
            reached: std::sync::atomic::AtomicBool::new(false),
        });
        let mut owner = crate::orchestration::OrchestrationStore::open_with_faults(
            &fixture.state_root,
            fault.clone(),
        )
        .unwrap();
        assert!(
            owner
                .refresh_checked_state(&fixture.view.workspace_id)
                .is_err()
        );
        assert!(fault.reached.load(std::sync::atomic::Ordering::SeqCst));
        assert_eq!(fs::read(&path).unwrap(), before);
    }

    #[test]
    fn collaboration_result_atomicity_replay_source_artifact_and_collection_progress() {
        let (fixture, session, source, target, mut ctx, request) = collaboration_fixture();
        fixture.initialize_writer_authority();
        let (first, terminal) = collaboration_accept(
            &fixture,
            session,
            source,
            target,
            &mut ctx,
            &request,
            "result-one",
        );
        let c = rusqlite::Connection::open(fixture.database()).unwrap();
        c.execute_batch("CREATE TRIGGER fail_result_outbox BEFORE INSERT ON collaboration_result_outbox BEGIN SELECT RAISE(ABORT,'result outbox fault'); END;").unwrap();
        assert!(
            crate::collaboration::settle_target(&fixture.state_root, target, &terminal).is_err()
        );
        for table in ["collaboration_results", "collaboration_result_outbox"] {
            assert_eq!(
                c.query_row(&format!("SELECT count(*) FROM {table}"), [], |r| r
                    .get::<_, u64>(0))
                    .unwrap(),
                0
            );
        }
        assert_eq!(
            c.query_row(
                "SELECT count(*) FROM result_content_refs WHERE owner_kind='collaboration_result'",
                [],
                |r| r.get::<_, u64>(0)
            )
            .unwrap(),
            0
        );
        assert_eq!(
            c.query_row(
                "SELECT execution_state FROM collaboration_exchanges",
                [],
                |r| r.get::<_, String>(0)
            )
            .unwrap(),
            "running"
        );
        c.execute_batch("DROP TRIGGER fail_result_outbox").unwrap();
        crate::collaboration::settle_target(&fixture.state_root, target, &terminal).unwrap();
        let artifact: String = c
            .query_row(
                "SELECT artifact_id FROM collaboration_results WHERE exchange_id=?1",
                [first.to_string()],
                |r| r.get(0),
            )
            .unwrap();
        crate::collaboration::settle_target(&fixture.state_root, target, &terminal).unwrap();
        let mut artifact_terminal = terminal.clone();
        let crate::turn::FinalResponse::Inline { text } = terminal.final_response.as_ref().unwrap()
        else {
            unreachable!()
        };
        let target_artifact = Uuid::now_v7();
        let target_directory = crate::run::run_root(&fixture.state_root, target).join("artifacts");
        fs::create_dir_all(&target_directory).unwrap();
        fs::set_permissions(&target_directory, fs::Permissions::from_mode(0o700)).unwrap();
        fs::write(
            target_directory.join(format!("{target_artifact}.bin")),
            text.as_bytes(),
        )
        .unwrap();
        artifact_terminal.final_response = Some(crate::turn::FinalResponse::Artifact {
            artifact_id: target_artifact,
            byte_length: text.len() as u64,
            sha256: crate::jcs::sha256_hex(text.as_bytes()),
            created_at: "2026-10-30T00:00:00Z".into(),
        });
        crate::collaboration::settle_target(&fixture.state_root, target, &artifact_terminal)
            .unwrap();
        let mut changed = terminal.clone();
        changed.final_response = Some(crate::turn::FinalResponse::Inline {
            text: "Changed bytes".into(),
        });
        assert!(
            crate::collaboration::settle_target(&fixture.state_root, target, &changed).is_err()
        );
        assert_eq!(c.query_row("SELECT count(*) FROM orchestration_events WHERE kind='collaboration_result_published'",[],|r|r.get::<_,u64>(0)).unwrap(),1);
        // A missing projection is rebuilt from SQLite under the original ID.
        fs::remove_file(
            crate::run::run_root(&fixture.state_root, source)
                .join("artifacts")
                .join(format!("{artifact}.bin")),
        )
        .unwrap();
        let broker =
            crate::orchestration::OrchestrationStore::open_observer(&fixture.state_root).unwrap();
        let carrier = broker
            .member_credential(source)
            .unwrap()
            .controller_carrier()
            .unwrap();
        let snapshot = crate::snapshot::RunSnapshot::load(&fixture.state_root, source, 0).unwrap();
        let chunk = crate::artifact::chunk(
            &fixture.state_root,
            &snapshot,
            &artifact,
            (0, 1024),
            Some(&carrier),
        )
        .unwrap();
        assert_eq!(chunk.data, "Safe answer result-one: 한글.".as_bytes());
        let foreign = crate::snapshot::RunSnapshot::load(&fixture.state_root, target, 0).unwrap();
        assert!(
            crate::artifact::chunk(
                &fixture.state_root,
                &foreign,
                &artifact,
                (0, 1024),
                Some(&carrier)
            )
            .is_err()
        );
        assert!(
            crate::artifact::chunk(&fixture.state_root, &snapshot, &artifact, (0, 1024), None)
                .is_err()
        );
        drop(broker);
        let (second, terminal) = collaboration_accept(
            &fixture,
            session,
            source,
            target,
            &mut ctx,
            &request,
            "result-two",
        );
        crate::collaboration::settle_target(&fixture.state_root, target, &terminal).unwrap();
        let collect = json!({"operation":"collect_collaboration_results","limit":1});
        ctx.source_tool_call_id = "lost-collect".into();
        let lost = collaboration_call(&fixture, &ctx, &collect).unwrap();
        assert_eq!(lost["results"][0]["exchange_id"], first.to_string());
        assert_eq!(lost["results"][0]["delivery_state"], "acknowledged");
        // The first result is deliberately treated as a lost response. A new
        // identity recovers it, then later calls progress to the next result.
        ctx.source_tool_call_id = "recover-lost".into();
        assert_eq!(collaboration_call(&fixture, &ctx, &collect).unwrap(), lost);
        ctx.source_tool_call_id = "next-pending".into();
        let next = collaboration_call(&fixture, &ctx, &collect).unwrap();
        assert_eq!(next["results"][0]["exchange_id"], second.to_string());
        ctx.source_tool_call_id = "lost-collect".into();
        assert_eq!(collaboration_call(&fixture, &ctx, &collect).unwrap(), lost);
        assert_eq!(
            collaboration_call(
                &fixture,
                &ctx,
                &json!({"operation":"collect_collaboration_results","limit":2})
            )
            .unwrap_err()
            .code,
            "COLLABORATION_IDEMPOTENCY_CONFLICT"
        );
        let (third, terminal) = collaboration_accept(
            &fixture,
            session,
            source,
            target,
            &mut ctx,
            &request,
            "result-three",
        );
        crate::collaboration::settle_target(&fixture.state_root, target, &terminal).unwrap();
        ctx.source_tool_call_id = "recover-two".into();
        assert_eq!(
            collaboration_call(&fixture, &ctx, &collect).unwrap()["results"][0]["exchange_id"],
            second.to_string()
        );
        ctx.source_tool_call_id = "deliver-three".into();
        assert_eq!(
            collaboration_call(&fixture, &ctx, &collect).unwrap()["results"][0]["exchange_id"],
            third.to_string()
        );
        // Source Turn/generation loss cannot erase these source-owned results.
        collaboration_core(
            &fixture,
            source,
            crate::domain::RunLifecycle::Running,
            Some("later-turn"),
        );
        let state_path = crate::run::run_root(&fixture.state_root, source).join("state.json");
        let mut state: Value = serde_json::from_slice(&fs::read(&state_path).unwrap()).unwrap();
        state["run_generation"] = json!(2);
        fs::write(&state_path, serde_json::to_vec(&state).unwrap()).unwrap();
        ctx.source_turn_id = "later-turn".into();
        ctx.source_tool_call_id = "after-restart".into();
        let recovered = collaboration_call(
            &fixture,
            &ctx,
            &json!({"operation":"collect_collaboration_results","limit":64}),
        )
        .unwrap();
        assert_eq!(recovered["results"].as_array().unwrap().len(), 3);
        assert!(
            recovered["results"]
                .as_array()
                .unwrap()
                .iter()
                .any(|r| r["result_artifact_ref"] == artifact)
        );
        let mut foreign_ctx = ctx.clone();
        foreign_ctx.source_run_id = target;
        collaboration_core(
            &fixture,
            target,
            crate::domain::RunLifecycle::Running,
            Some("later-turn"),
        );
        let forbidden = json!({"operation":"await_consultations","exchange_ids":[first],"return_when":"any","transport_wait_seconds":1});
        assert_eq!(
            collaboration_call(&fixture, &foreign_ctx, &forbidden)
                .unwrap_err()
                .code,
            "COLLABORATION_NOT_ALLOWED"
        );
        assert_eq!(
            c.query_row("SELECT count(*) FROM collaboration_results", [], |r| r
                .get::<_, u64>(0))
                .unwrap(),
            3
        );
        assert_eq!(
            c.query_row(
                "SELECT count(*) FROM collaboration_execution_links",
                [],
                |r| r.get::<_, u64>(0)
            )
            .unwrap(),
            3
        );
    }

    fn collaboration_spawn_call(
        root: PathBuf,
        ctx: crate::orchestration::PrimaryCallContext,
        request: Value,
    ) -> std::thread::JoinHandle<Result<Value, MachineError>> {
        std::thread::spawn(move || {
            let mut store = crate::orchestration::OrchestrationStore::open(&root)?;
            let mut effects = crate::semantic::ProductionOrchestrationEffects::new(&root);
            crate::collaboration::admit(&mut store, &ctx, &request, &mut effects)
        })
    }
    fn collaboration_wait_count(fixture: &Fixture, expected: u64) {
        let c = rusqlite::Connection::open(fixture.database()).unwrap();
        let deadline = std::time::Instant::now() + Duration::from_secs(3);
        loop {
            let count: u64 = c
                .query_row(
                    "SELECT count(*) FROM collaboration_waits WHERE active=1",
                    [],
                    |r| r.get(0),
                )
                .unwrap();
            if count == expected {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "wait admission did not settle: {count} != {expected}"
            );
            std::thread::sleep(Duration::from_millis(5));
        }
    }

    fn collaboration_abandon_wait(
        fixture: &Fixture,
        context: &crate::orchestration::PrimaryCallContext,
        payload: Value,
    ) -> Result<(), MachineError> {
        let state = crate::run::RunStore::new(
            crate::workspace::SystemWorkspacePlatform,
            &fixture.state_root,
        )
        .load_state_projection(context.source_run_id)?;
        let call = crate::turn::PrimaryToolCall {
            tool_name: crate::collaboration::TOOL_NAME.into(),
            source_thread_id: state.thread_id.unwrap(),
            request_id: 93,
            run_generation: state.run_generation,
            context: context.clone(),
            payload,
        };
        // The lifetime callback runs after registration commits. Unwinding
        // there models a lost Worker without running ordinary waiter cleanup.
        let lost = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            crate::collaboration::dispatch(
                &fixture.state_root,
                &call,
                context.source_run_id,
                state.run_generation,
                &fixture.view.workspace_id,
                &|| panic!("fixture lost waiter after committed registration"),
            )
        }));
        match lost {
            Err(panic) => {
                assert_eq!(
                    panic.downcast_ref::<&str>(),
                    Some(&"fixture lost waiter after committed registration")
                );
                Ok(())
            }
            Ok(Err(error)) => Err(error),
            Ok(Ok(_)) => panic!("pending wait did not reach its lifetime callback"),
        }
    }

    #[test]
    fn collaboration_abandoned_waits_reconcile_currency_loss_and_reclaim_both_slots() {
        for loss in ["generation", "turn", "lifecycle"] {
            let (fixture, session, source, target, mut ctx, request) = collaboration_fixture();
            fixture.initialize_writer_authority();
            let queued = collaboration_call(&fixture, &ctx, &request).unwrap();
            let exchange = Uuid::parse_str(queued["exchange_id"].as_str().unwrap()).unwrap();
            let db = rusqlite::Connection::open(fixture.database()).unwrap();
            let accepted = crate::collaboration::execution_record(&db, exchange).unwrap();
            // Mark the fixture's original Source task delivered so only its
            // outbound consultation and wait affect this idle-mail guard.
            db.execute(
                "UPDATE brokered_tasks SET state='delivered' WHERE target_run_id=?1",
                [source.to_string()],
            )
            .unwrap();
            let actor = crate::scheduler::Actor {
                owner: crate::assignment_queue::Owner::Managed(session),
                run: source,
            };
            assert!(
                crate::scheduler::candidates(&db, actor.owner, source)
                    .unwrap()
                    .is_empty()
            );
            assert_eq!(
                db.query_row(
                    "SELECT count(*) FROM scheduler_claims WHERE target_run_id=?1",
                    [source.to_string()],
                    |r| r.get::<_, u64>(0)
                )
                .unwrap(),
                0
            );
            assert_eq!(
                db.query_row(
                    "SELECT count(*) FROM collaboration_result_outbox WHERE source_run_id=?1",
                    [source.to_string()],
                    |r| r.get::<_, u64>(0)
                )
                .unwrap(),
                0
            );
            crate::scheduler::idle_mail_guards(&db, actor).unwrap();
            let mailbox = db
                .query_row(
                    "SELECT sequence,target_run_id FROM collaboration_mailbox WHERE exchange_id=?1",
                    [exchange.to_string()],
                    |r| Ok((r.get::<_, u64>(0)?, r.get::<_, String>(1)?)),
                )
                .unwrap();
            let wait = json!({"operation":"await_consultations","exchange_ids":[exchange],"return_when":"all","transport_wait_seconds":60});
            for call in ["lost-first", "lost-second"] {
                ctx.source_tool_call_id = call.into();
                collaboration_abandon_wait(&fixture, &ctx, wait.clone()).unwrap();
            }
            let retained = {
                let mut s = db.prepare("SELECT wait_id,request_sha256,expires_at_ms FROM collaboration_waits ORDER BY wait_id").unwrap();
                s.query_map([], |r| {
                    Ok((
                        r.get::<_, String>(0)?,
                        r.get::<_, String>(1)?,
                        r.get::<_, i64>(2)?,
                    ))
                })
                .unwrap()
                .collect::<Result<Vec<_>, _>>()
                .unwrap()
            };
            assert_eq!(retained.len(), 2);
            assert_eq!(
                db.query_row(
                    "SELECT count(*) FROM collaboration_waits WHERE active=1",
                    [],
                    |r| r.get::<_, u64>(0)
                )
                .unwrap(),
                2
            );
            assert_eq!(
                db.query_row("SELECT count(*) FROM collaboration_wait_edges", [], |r| r
                    .get::<_, u64>(
                    0
                ))
                .unwrap(),
                2
            );
            assert_eq!(db.query_row("SELECT count(*) FROM orchestration_events WHERE kind='collaboration_wait_ended'", [], |r| r.get::<_,u64>(0)).unwrap(), 0);
            assert_eq!(
                crate::scheduler::idle_mail_guards(&db, actor)
                    .unwrap_err()
                    .details["reason"],
                "actor_has_blocking_wait"
            );

            let path = crate::run::run_root(&fixture.state_root, source).join("state.json");
            let mut state: crate::projection::RunStateProjection =
                serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();
            match loss {
                "generation" => state.run_generation += 1,
                "turn" => state.active_turn_id = Some("different-turn".into()),
                "lifecycle" => state.lifecycle = crate::domain::RunLifecycle::Idle,
                _ => unreachable!(),
            }
            fs::write(&path, serde_json::to_vec(&state).unwrap()).unwrap();
            drop(db);
            crate::collaboration::reconcile_waits(&fixture.state_root).unwrap();
            crate::collaboration::reconcile_waits(&fixture.state_root).unwrap();
            let db = rusqlite::Connection::open(fixture.database()).unwrap();
            for (id, digest, until) in &retained {
                assert_eq!(db.query_row("SELECT request_sha256,expires_at_ms,active FROM collaboration_waits WHERE wait_id=?1", [id], |r| Ok((r.get::<_,String>(0)?,r.get::<_,i64>(1)?,r.get::<_,bool>(2)?))).unwrap(), (digest.clone(), *until, false));
            }
            assert_eq!(
                db.query_row("SELECT count(*) FROM collaboration_wait_edges", [], |r| r
                    .get::<_, u64>(
                    0
                ))
                .unwrap(),
                0
            );
            crate::scheduler::idle_mail_guards(&db, actor).unwrap();
            state.lifecycle = crate::domain::RunLifecycle::Running;
            state.active_turn_id = Some("fresh-source-turn".into());
            state.latest_turn_id = state.active_turn_id.clone();
            fs::write(&path, serde_json::to_vec(&state).unwrap()).unwrap();
            ctx.source_turn_id = "fresh-source-turn".into();
            for call in ["fresh-first", "fresh-second"] {
                ctx.source_tool_call_id = call.into();
                collaboration_abandon_wait(&fixture, &ctx, wait.clone()).unwrap();
            }
            ctx.source_tool_call_id = "fresh-third".into();
            assert_eq!(
                collaboration_abandon_wait(&fixture, &ctx, wait)
                    .unwrap_err()
                    .code,
                "COLLABORATION_NOT_ALLOWED"
            );
            assert_eq!(
                db.query_row(
                    "SELECT count(*) FROM collaboration_waits WHERE active=1",
                    [],
                    |r| r.get::<_, u64>(0)
                )
                .unwrap(),
                2
            );
            state.lifecycle = crate::domain::RunLifecycle::Idle;
            fs::write(&path, serde_json::to_vec(&state).unwrap()).unwrap();
            crate::collaboration::reconcile_waits(&fixture.state_root).unwrap();
            crate::scheduler::idle_mail_guards(&db, actor).unwrap();
            let after = crate::collaboration::execution_record(&db, exchange).unwrap();
            assert_eq!(
                (
                    after.session,
                    after.target,
                    after.event_digest,
                    after.deadline_ms,
                    after.prompt
                ),
                (
                    session,
                    target,
                    accepted.event_digest,
                    accepted.deadline_ms,
                    accepted.prompt
                )
            );
            assert_eq!(
                db.query_row(
                    "SELECT sequence,target_run_id FROM collaboration_mailbox WHERE exchange_id=?1",
                    [exchange.to_string()],
                    |r| Ok((r.get::<_, u64>(0)?, r.get::<_, String>(1)?))
                )
                .unwrap(),
                mailbox
            );
            assert_eq!(db.query_row("SELECT execution_state,delivery_state FROM collaboration_exchanges WHERE exchange_id=?1", [exchange.to_string()], |r| Ok((r.get::<_,String>(0)?,r.get::<_,String>(1)?))).unwrap(), ("queued".into(), "none".into()));
        }
    }

    #[test]
    fn collaboration_abandoned_wait_edge_cannot_form_a_cycle_after_restart() {
        let (fixture, session, a, b, mut ca, request) = collaboration_fixture();
        fixture.initialize_writer_authority();
        let mut cb = collaboration_prepare_source(
            &fixture,
            session,
            b,
            &FakePort::new(),
            "reverse-root",
            "reverse-turn",
        );
        let ab = Uuid::parse_str(
            collaboration_call(&fixture, &ca, &request).unwrap()["exchange_id"]
                .as_str()
                .unwrap(),
        )
        .unwrap();
        let mut reverse = request;
        reverse["target"] = json!({"run_id":a});
        let ba = Uuid::parse_str(
            collaboration_call(&fixture, &cb, &reverse).unwrap()["exchange_id"]
                .as_str()
                .unwrap(),
        )
        .unwrap();
        let wait = |id| json!({"operation":"await_consultations","exchange_ids":[id],"return_when":"all","transport_wait_seconds":60});
        ca.source_tool_call_id = "abandoned-a-edge".into();
        collaboration_abandon_wait(&fixture, &ca, wait(ab)).unwrap();
        collaboration_wait_count(&fixture, 1);
        cb.source_tool_call_id = "real-cycle".into();
        assert_eq!(
            collaboration_abandon_wait(&fixture, &cb, wait(ba))
                .unwrap_err()
                .code,
            "COLLABORATION_WAIT_CYCLE"
        );
        collaboration_core(
            &fixture,
            a,
            crate::domain::RunLifecycle::Running,
            Some("replacement-turn"),
        );
        crate::collaboration::reconcile_waits(&fixture.state_root).unwrap();
        collaboration_wait_count(&fixture, 0);
        let db = rusqlite::Connection::open(fixture.database()).unwrap();
        assert_eq!(
            db.query_row("SELECT count(*) FROM collaboration_wait_edges", [], |r| r
                .get::<_, u64>(
                0
            ))
            .unwrap(),
            0
        );
        cb.source_tool_call_id = "no-stale-cycle".into();
        collaboration_abandon_wait(&fixture, &cb, wait(ba)).unwrap();
        collaboration_wait_count(&fixture, 1);
        collaboration_core(&fixture, b, crate::domain::RunLifecycle::Idle, None);
        crate::collaboration::reconcile_waits(&fixture.state_root).unwrap();
        collaboration_wait_count(&fixture, 0);
        assert_eq!(
            db.query_row(
                "SELECT count(*) FROM collaboration_exchanges WHERE execution_state='queued'",
                [],
                |r| r.get::<_, u64>(0)
            )
            .unwrap(),
            2
        );
        assert!(crate::collaboration::execution_record(&db, ab).is_ok());
        assert!(crate::collaboration::execution_record(&db, ba).is_ok());
    }

    #[test]
    fn collaboration_any_all_waits_release_mutation_owner_and_preserve_original_expiry() {
        let (fixture, session, source, target, mut ctx, request) = collaboration_fixture();
        fixture.initialize_writer_authority();
        let (first, terminal) = collaboration_accept(
            &fixture,
            session,
            source,
            target,
            &mut ctx,
            &request,
            "any-result",
        );
        crate::collaboration::settle_target(&fixture.state_root, target, &terminal).unwrap();
        ctx.source_tool_call_id = "pending-request".into();
        let queued = collaboration_call(&fixture, &ctx, &request).unwrap();
        let second = Uuid::parse_str(queued["exchange_id"].as_str().unwrap()).unwrap();
        let any = json!({"operation":"await_consultations","exchange_ids":[second,first],"return_when":"any","transport_wait_seconds":1});
        ctx.source_tool_call_id = "any-call".into();
        let response = collaboration_call(&fixture, &ctx, &any).unwrap();
        assert_eq!(response["completed"][0]["exchange_id"], first.to_string());
        assert_eq!(response["pending"], json!([second]));
        let all = json!({"operation":"await_consultations","exchange_ids":[second,first],"return_when":"all","transport_wait_seconds":1});
        ctx.source_tool_call_id = "all-call".into();
        let waiting =
            collaboration_spawn_call(fixture.state_root.clone(), ctx.clone(), all.clone());
        collaboration_wait_count(&fixture, 1);
        let mut concurrent = EngagementStore::open(&fixture.database()).unwrap();
        concurrent
            .transact(|tx| {
                crate::orchestration::append_event(
                    tx,
                    session,
                    "test_concurrent_wait_observation",
                    &crate::jcs::sha256_hex(b"not blocked"),
                    now_ms()?,
                )
            })
            .unwrap();
        assert!(crate::collaboration::dependency_unblock(concurrent.connection(), second).unwrap());
        let rows = crate::scheduler::candidates(
            concurrent.connection(),
            crate::assignment_queue::Owner::Managed(session),
            target,
        )
        .unwrap();
        assert!(
            rows.iter()
                .find(|r| r.id == second)
                .unwrap()
                .dependency_unblock
        );
        let snapshot = waiting.join().unwrap().unwrap();
        assert_eq!(snapshot["pending"], json!([second]));
        collaboration_wait_count(&fixture, 0);
        let c = rusqlite::Connection::open(fixture.database()).unwrap();
        let until: i64 = c
            .query_row(
                "SELECT expires_at_ms FROM collaboration_waits WHERE call_id='all-call'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(collaboration_call(&fixture, &ctx, &all).unwrap(), snapshot);
        assert_eq!(
            c.query_row(
                "SELECT expires_at_ms FROM collaboration_waits WHERE call_id='all-call'",
                [],
                |r| r.get::<_, i64>(0)
            )
            .unwrap(),
            until
        );
        assert_eq!(
            c.query_row(
                "SELECT execution_state FROM collaboration_exchanges WHERE exchange_id=?1",
                [second.to_string()],
                |r| r.get::<_, String>(0)
            )
            .unwrap(),
            "queued"
        );
        assert!(
            !crate::collaboration::dependency_unblock(concurrent.connection(), second).unwrap()
        );
        // Simulate loss before response persistence, retaining the admitted
        // transport origin: a restarted same-call wait gets no fresh second.
        c.execute(
            "DELETE FROM collaboration_tool_receipts WHERE call_id='all-call'",
            [],
        )
        .unwrap();
        let start = std::time::Instant::now();
        let _ = collaboration_call(&fixture, &ctx, &all).unwrap();
        assert!(start.elapsed() < Duration::from_millis(500));
        assert_eq!(
            c.query_row(
                "SELECT expires_at_ms FROM collaboration_waits WHERE call_id='all-call'",
                [],
                |r| r.get::<_, i64>(0)
            )
            .unwrap(),
            until
        );
        // Actual Worker dispatcher and closed native await response path.
        let (native, envelope, _) = crate::turn::tests::native_worker_completion(
            &fixture.state_root,
            source,
            &fixture.view.workspace_id,
            &fixture.view.canonical_path.to_path_buf().unwrap(),
            crate::collaboration::TOOL_NAME,
            any,
        )
        .unwrap();
        assert_eq!(envelope["success"], true);
        assert_eq!(native["completed"][0]["exchange_id"], first.to_string());
    }

    #[test]
    fn collaboration_wait_graph_cycles_depth_count_writer_and_atomic_blocking_submit() {
        let mut policy = managed_policy();
        policy.roles[0].collaboration_source = true;
        policy.roles[0].collaboration_target = true;
        policy.roles[0].max_active_instances = 4;
        let (fixture, session, a, b, mut ca, mut request) = collaboration_fixture_policy(policy);
        fixture.initialize_writer_authority();
        let port = FakePort::new();
        let c = Uuid::parse_str(
            &fixture
                .spawn_member(session, "graph-c", &port)
                .member
                .member_ref,
        )
        .unwrap();
        let d = Uuid::parse_str(
            &fixture
                .spawn_member(session, "graph-d", &port)
                .member
                .member_ref,
        )
        .unwrap();
        let mut cb =
            collaboration_prepare_source(&fixture, session, b, &port, "graph-root-b", "turn-b");
        let mut cc =
            collaboration_prepare_source(&fixture, session, c, &port, "graph-root-c", "turn-c");
        let mut cd =
            collaboration_prepare_source(&fixture, session, d, &port, "graph-root-d", "turn-d");
        let submit =
            |ctx: &mut crate::orchestration::PrimaryCallContext, target: Uuid, label: &str| {
                ctx.source_tool_call_id = label.into();
                let mut payload = request.clone();
                payload["target"] = json!({"run_id":target});
                Uuid::parse_str(
                    collaboration_call(&fixture, ctx, &payload).unwrap()["exchange_id"]
                        .as_str()
                        .unwrap(),
                )
                .unwrap()
            };
        let ab = submit(&mut ca, b, "a-to-b");
        let ba = submit(&mut cb, a, "b-to-a");
        let bc = submit(&mut cb, c, "b-to-c");
        let c_to_a = submit(&mut cc, a, "c-to-a");
        let da = submit(&mut cd, a, "d-to-a");
        let wait = |ids: Vec<Uuid>| json!({"operation":"await_consultations","exchange_ids":ids,"return_when":"all","transport_wait_seconds":5});
        let refusal = |error: MachineError, code: &str| {
            assert_eq!(error.code, code);
            let projected = crate::collaboration::error_result(&error);
            assert_eq!(projected["operation"], "collaboration_error");
            assert_eq!(projected["code"], code);
            assert_eq!(projected["retryable"], false);
            assert!(
                !projected
                    .to_string()
                    .contains(fixture.state_root.to_str().unwrap())
            );
        };
        ca.source_tool_call_id = "wait-a".into();
        let wa = collaboration_spawn_call(fixture.state_root.clone(), ca.clone(), wait(vec![ab]));
        collaboration_wait_count(&fixture, 1);
        cb.source_tool_call_id = "direct-cycle".into();
        refusal(
            collaboration_call(&fixture, &cb, &wait(vec![ba])).unwrap_err(),
            "COLLABORATION_WAIT_CYCLE",
        );
        cb.source_tool_call_id = "atomic-set-cycle".into();
        assert_eq!(
            collaboration_call(&fixture, &cb, &wait(vec![bc, ba]))
                .unwrap_err()
                .code,
            "COLLABORATION_WAIT_CYCLE"
        );
        collaboration_wait_count(&fixture, 1);
        cb.source_tool_call_id = "wait-b".into();
        let wb = collaboration_spawn_call(fixture.state_root.clone(), cb.clone(), wait(vec![bc]));
        collaboration_wait_count(&fixture, 2);
        cc.source_tool_call_id = "transitive-cycle".into();
        refusal(
            collaboration_call(&fixture, &cc, &wait(vec![c_to_a])).unwrap_err(),
            "COLLABORATION_WAIT_CYCLE",
        );
        cd.source_tool_call_id = "depth-three".into();
        refusal(
            collaboration_call(&fixture, &cd, &wait(vec![da])).unwrap_err(),
            "COLLABORATION_DEPTH_EXCEEDED",
        );
        ca.source_tool_call_id = "wait-a-second".into();
        let wa2 = collaboration_spawn_call(fixture.state_root.clone(), ca.clone(), wait(vec![ab]));
        collaboration_wait_count(&fixture, 3);
        ca.source_tool_call_id = "wait-a-third".into();
        assert_eq!(
            collaboration_call(&fixture, &ca, &wait(vec![ab]))
                .unwrap_err()
                .code,
            "COLLABORATION_NOT_ALLOWED"
        );
        let db = rusqlite::Connection::open(fixture.database()).unwrap();
        let before: u64 = db
            .query_row("SELECT count(*) FROM collaboration_exchanges", [], |r| {
                r.get(0)
            })
            .unwrap();
        ca.source_tool_call_id = "blocking-cap-refused".into();
        request["blocking"] = json!(true);
        assert_eq!(
            collaboration_call(&fixture, &ca, &request)
                .unwrap_err()
                .code,
            "COLLABORATION_NOT_ALLOWED"
        );
        assert_eq!(
            db.query_row("SELECT count(*) FROM collaboration_exchanges", [], |r| r
                .get::<_, u64>(0))
                .unwrap(),
            before
        );
        collaboration_core(&fixture, a, crate::domain::RunLifecycle::Idle, None);
        collaboration_core(&fixture, b, crate::domain::RunLifecycle::Idle, None);
        crate::collaboration::notify_waiters(a);
        crate::collaboration::notify_waiters(b);
        for thread in [wa, wa2, wb] {
            refusal(thread.join().unwrap().unwrap_err(), "INTERRUPTED_UNKNOWN");
        }
        collaboration_wait_count(&fixture, 0);
        assert_eq!(
            db.query_row("SELECT count(*) FROM collaboration_wait_edges", [], |r| r
                .get::<_, u64>(
                0
            ))
            .unwrap(),
            0
        );
        assert_eq!(
            db.query_row(
                "SELECT count(*) FROM collaboration_exchanges WHERE execution_state='queued'",
                [],
                |r| r.get::<_, u64>(0)
            )
            .unwrap(),
            before
        );
        collaboration_core(
            &fixture,
            a,
            crate::domain::RunLifecycle::Running,
            Some(&ca.source_turn_id),
        );
        let manifest = crate::run::RunStore::new(
            crate::workspace::SystemWorkspacePlatform,
            &fixture.state_root,
        )
        .load_manifest(a)
        .unwrap();
        let writer = crate::writer::WriterStore::new(
            &fixture.state_root,
            &fixture.view.workspace_id,
            crate::darwin::DarwinSystem.current_uid(),
        );
        let operation = Uuid::now_v7();
        let holder = crate::writer::WriterStore::holder(
            a,
            "fixture".into(),
            &manifest.controller,
            1,
            "a".repeat(64),
            1,
            Some("native-thread".into()),
            crate::domain::RunLifecycle::Running,
        );
        let (_, (_, generation)) = writer
            .transact(|w| w.prepare_acquire(a, holder, operation))
            .unwrap();
        for reserved in [true, false] {
            if !reserved {
                writer
                    .transact(|w| w.commit_acquire(operation, generation))
                    .unwrap();
            }
            ca.source_tool_call_id = if reserved {
                "writer-reserved"
            } else {
                "writer-active"
            }
            .into();
            let original = writer.load().unwrap();
            refusal(
                collaboration_call(&fixture, &ca, &wait(vec![ab])).unwrap_err(),
                "COLLABORATION_WRITER_HELD",
            );
            refusal(
                collaboration_call(&fixture, &ca, &request).unwrap_err(),
                "COLLABORATION_WRITER_HELD",
            );
            assert_eq!(writer.load().unwrap(), original);
        }
        request["blocking"] = json!(false);
        ca.source_tool_call_id = "writer-nonblocking".into();
        assert!(collaboration_call(&fixture, &ca, &request).is_ok());
        assert_eq!(
            db.query_row("SELECT count(*) FROM collaboration_wait_edges", [], |r| r
                .get::<_, u64>(
                0
            ))
            .unwrap(),
            0
        );
    }

    #[test]
    fn collaboration_nested_root_priority_deadline_and_nonblocking_residency_are_durable() {
        let mut policy = managed_policy();
        policy.roles[0].collaboration_source = true;
        policy.roles[0].collaboration_target = true;
        policy.roles[0].max_active_instances = 3;
        let (fixture, session, a, b, mut ca, request) = collaboration_fixture_policy(policy);
        fixture.initialize_writer_authority();
        let port = FakePort::new();
        let c = Uuid::parse_str(
            &fixture
                .spawn_member(session, "nested-c", &port)
                .member
                .member_ref,
        )
        .unwrap();
        fixture.publish_member_manifest(session, c);
        collaboration_core(&fixture, c, crate::domain::RunLifecycle::Idle, None);
        let (parent, terminal) = collaboration_accept(
            &fixture,
            session,
            a,
            b,
            &mut ca,
            &request,
            "parent-consultation",
        );
        collaboration_core(
            &fixture,
            b,
            crate::domain::RunLifecycle::Running,
            Some(&terminal.turn_id),
        );
        let child_context = crate::orchestration::PrimaryCallContext {
            session_id: session,
            source_run_id: b,
            source_turn_id: terminal.turn_id.clone(),
            source_tool_call_id: "nested-call".into(),
            idempotency_key: "not-authority".into(),
        };
        let mut nested = request.clone();
        nested["target"] = json!({"run_id":c});
        nested["deadline_seconds"] = json!(3600);
        let child = Uuid::parse_str(
            collaboration_call(&fixture, &child_context, &nested).unwrap()["exchange_id"]
                .as_str()
                .unwrap(),
        )
        .unwrap();
        let db = rusqlite::Connection::open(fixture.database()).unwrap();
        let root:(String,u8,i64)=db.query_row("SELECT root_task_id,root_priority,deadline_ms FROM collaboration_exchanges WHERE exchange_id=?1",[parent.to_string()],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).unwrap();
        let inherited:(String,u8,i64,String,u8)=db.query_row("SELECT e.root_task_id,e.root_priority,e.deadline_ms,l.parent_exchange_id,l.hop_depth FROM collaboration_exchanges e JOIN collaboration_lineage l USING(exchange_id) WHERE exchange_id=?1",[child.to_string()],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?,r.get(4)?))).unwrap();
        assert_eq!((inherited.0, inherited.1, inherited.2), root);
        assert_eq!(inherited.3, parent.to_string());
        assert_eq!(inherited.4, 2);
        assert!(crate::collaboration::execution_record(&db, child).is_ok());
        // A caller cannot name a parent or priority through the closed request.
        let mut forged = nested.clone();
        forged["parent_exchange_id"] = json!(parent);
        assert_eq!(
            collaboration_call(&fixture, &child_context, &forged)
                .unwrap_err()
                .code,
            "COLLABORATION_NOT_ALLOWED"
        );
        let saved: String = db
            .query_row(
                "SELECT provenance_sha256 FROM collaboration_lineage WHERE exchange_id=?1",
                [child.to_string()],
                |r| r.get(0),
            )
            .unwrap();
        db.execute(
            "UPDATE collaboration_lineage SET provenance_sha256='forged' WHERE exchange_id=?1",
            [child.to_string()],
        )
        .unwrap();
        assert!(crate::collaboration::execution_record(&db, child).is_err());
        db.execute(
            "UPDATE collaboration_lineage SET provenance_sha256=?2 WHERE exchange_id=?1",
            rusqlite::params![child.to_string(), saved],
        )
        .unwrap();
        // Independent nonblocking work does not pin its source Worker after
        // the original task has been delivered. Target execution remains fenced.
        db.execute(
            "UPDATE brokered_tasks SET state='delivered' WHERE task_id=?1",
            [root.0],
        )
        .unwrap();
        collaboration_core(&fixture, a, crate::domain::RunLifecycle::Idle, None);
        let actor = crate::scheduler::Actor {
            owner: crate::assignment_queue::Owner::Managed(session),
            run: a,
        };
        crate::scheduler::idle_mail_guards(&db, actor).unwrap();
        let target_actor = crate::scheduler::Actor { run: b, ..actor };
        assert!(crate::scheduler::idle_mail_guards(&db, target_actor).is_err());
        crate::collaboration::settle_target(&fixture.state_root, b, &terminal).unwrap();
        assert!(crate::scheduler::idle_mail_guards(&db, actor).is_err());
        collaboration_core(
            &fixture,
            a,
            crate::domain::RunLifecycle::Running,
            Some("new-source-turn"),
        );
        ca.source_turn_id = "new-source-turn".into();
        ca.source_tool_call_id = "collect-result".into();
        let result = collaboration_call(
            &fixture,
            &ca,
            &json!({"operation":"collect_collaboration_results","limit":1}),
        )
        .unwrap();
        assert_eq!(result["results"][0]["exchange_id"], parent.to_string());
        collaboration_core(&fixture, a, crate::domain::RunLifecycle::Idle, None);
        crate::scheduler::idle_mail_guards(&db, actor).unwrap();
        assert_eq!(
            db.query_row(
                "SELECT count(*) FROM collaboration_execution_links",
                [],
                |r| r.get::<_, u64>(0)
            )
            .unwrap(),
            1
        );
    }

    #[test]
    fn collaboration_worker_wait_uses_checked_notifications_and_lifetime_without_sql_polling() {
        let (fixture, session, source, _target, mut ctx, request) = collaboration_fixture();
        fixture.initialize_writer_authority();
        ctx.source_tool_call_id = "queued-before-wait".into();
        let queued = collaboration_call(&fixture, &ctx, &request).unwrap();
        let exchange = Uuid::parse_str(queued["exchange_id"].as_str().unwrap()).unwrap();
        let db = rusqlite::Connection::open(fixture.database()).unwrap();
        let deadline: i64 = db
            .query_row("SELECT deadline_ms FROM collaboration_exchanges", [], |r| {
                r.get(0)
            })
            .unwrap();
        let worker = crate::worker::tests::PrimaryWorkerFixture::new(
            &fixture.state_root,
            source,
            &fixture.view.workspace_id,
        );
        ctx.source_tool_call_id = "native-notification-wait".into();
        worker.dispatcher.dispatch(crate::turn::PrimaryToolCall {tool_name:crate::collaboration::TOOL_NAME.into(),source_thread_id:"native-thread".into(),request_id:91,run_generation:1,context:ctx,payload:json!({"operation":"await_consultations","exchange_ids":[exchange],"return_when":"all","transport_wait_seconds":5})}).unwrap();
        collaboration_wait_count(&fixture, 1);
        let until = std::time::Instant::now() + Duration::from_secs(2);
        while crate::collaboration::wait_observations(source) == 0 {
            assert!(std::time::Instant::now() < until);
            std::thread::yield_now();
        }
        let reads = crate::collaboration::wait_observations(source);
        std::thread::sleep(Duration::from_millis(250));
        assert_eq!(crate::collaboration::wait_observations(source), reads);
        for (generation, build) in [(true, false), (false, true)] {
            assert!(matches!(
                crate::worker::tests::collaboration_control_hint(source, generation, build),
                crate::worker::ControlResponseV1::Rejected { .. }
            ));
            assert_eq!(crate::collaboration::wait_observations(source), reads);
        }
        assert!(matches!(
            crate::worker::tests::collaboration_control_hint(source, false, false),
            crate::worker::ControlResponseV1::Status { .. }
        ));
        let until = std::time::Instant::now() + Duration::from_secs(2);
        while crate::collaboration::wait_observations(source) == reads {
            assert!(std::time::Instant::now() < until);
            std::thread::yield_now();
        }
        let reads = crate::collaboration::wait_observations(source);
        std::thread::sleep(Duration::from_millis(250));
        assert_eq!(crate::collaboration::wait_observations(source), reads);
        // A real mailbox stop invalidates the original tool lifetime even
        // before the fixture's durable projection changes or timeout expires.
        worker.stop();
        let completion = worker.completion();
        assert_eq!(completion.result.unwrap_err().code, "INTERRUPTED_UNKNOWN");
        collaboration_wait_count(&fixture, 0);
        assert_eq!(
            db.query_row(
                "SELECT execution_state FROM collaboration_exchanges",
                [],
                |r| r.get::<_, String>(0)
            )
            .unwrap(),
            "queued"
        );
        assert_eq!(
            db.query_row("SELECT deadline_ms FROM collaboration_exchanges", [], |r| r
                .get::<_, i64>(0))
                .unwrap(),
            deadline
        );
        assert_eq!(
            db.query_row("SELECT count(*) FROM collaboration_wait_edges", [], |r| r
                .get::<_, u64>(
                0
            ))
            .unwrap(),
            0
        );
        assert_eq!(
            db.query_row(
                "SELECT count(*) FROM collaboration_waits WHERE session_id=?1",
                [session.to_string()],
                |r| r.get::<_, u64>(0)
            )
            .unwrap(),
            1
        );
    }

    #[test]
    fn collaboration_concurrent_collectors_and_failed_receipt_do_not_skip_pending_results() {
        let (fixture, session, source, target, mut ctx, request) = collaboration_fixture();
        fixture.initialize_writer_authority();
        let mut ids = Vec::new();
        for label in ["concurrent-one", "concurrent-two", "concurrent-three"] {
            let (id, terminal) =
                collaboration_accept(&fixture, session, source, target, &mut ctx, &request, label);
            crate::collaboration::settle_target(&fixture.state_root, target, &terminal).unwrap();
            ids.push(id);
        }
        let db = rusqlite::Connection::open(fixture.database()).unwrap();
        db.execute_batch("CREATE TRIGGER fail_collection_receipt BEFORE INSERT ON collaboration_tool_receipts WHEN NEW.call_id='fault-collect' BEGIN SELECT RAISE(ABORT,'collection receipt fault'); END;").unwrap();
        let request = json!({"operation":"collect_collaboration_results","limit":1});
        ctx.source_tool_call_id = "fault-collect".into();
        assert!(collaboration_call(&fixture, &ctx, &request).is_err());
        assert_eq!(
            db.query_row(
                "SELECT count(*) FROM collaboration_exchanges WHERE delivery_state='acknowledged'",
                [],
                |r| r.get::<_, u64>(0)
            )
            .unwrap(),
            0
        );
        db.execute_batch("DROP TRIGGER fail_collection_receipt")
            .unwrap();
        let mut collectors = Vec::new();
        for label in ["collector-a", "collector-b"] {
            let mut call = ctx.clone();
            call.source_tool_call_id = label.into();
            collectors.push((
                call.clone(),
                collaboration_spawn_call(fixture.state_root.clone(), call, request.clone()),
            ));
        }
        for (call, thread) in collectors {
            let response = thread.join().unwrap().unwrap();
            assert_eq!(response["results"][0]["exchange_id"], ids[0].to_string());
            assert_eq!(
                collaboration_call(&fixture, &call, &request).unwrap(),
                response
            );
        }
        ctx.source_tool_call_id = "changed-limit".into();
        let response = collaboration_call(
            &fixture,
            &ctx,
            &json!({"operation":"collect_collaboration_results","limit":2}),
        )
        .unwrap();
        assert_eq!(response["results"].as_array().unwrap().len(), 2);
        assert!(
            response["results"]
                .as_array()
                .unwrap()
                .iter()
                .any(|r| r["exchange_id"] == ids[1].to_string())
        );
        ctx.source_tool_call_id = "after-changed-limit".into();
        assert_eq!(
            collaboration_call(&fixture, &ctx, &request).unwrap()["results"][0]["exchange_id"],
            ids[2].to_string()
        );
        assert_eq!(
            db.query_row(
                "SELECT count(*) FROM collaboration_execution_links",
                [],
                |r| r.get::<_, u64>(0)
            )
            .unwrap(),
            3
        );
        assert_eq!(
            db.query_row(
                "SELECT count(*) FROM collaboration_result_outbox",
                [],
                |r| r.get::<_, u64>(0)
            )
            .unwrap(),
            3
        );
    }

    #[test]
    fn collaboration_blocking_submit_returns_original_queued_receipt_after_terminal_without_rewait()
    {
        let (fixture, session, source, target, mut ctx, mut request) = collaboration_fixture();
        fixture.initialize_writer_authority();
        collaboration_captured_controller(&fixture, source);
        collaboration_captured_controller(&fixture, target);
        collaboration_observable_core(&fixture, source);
        collaboration_observable_core(&fixture, target);
        ctx.source_tool_call_id = "blocking-submit".into();
        request["blocking"] = json!(true);
        request["deadline_seconds"] = json!(2);
        let pending =
            collaboration_spawn_call(fixture.state_root.clone(), ctx.clone(), request.clone());
        collaboration_wait_count(&fixture, 1);
        let db = rusqlite::Connection::open(fixture.database()).unwrap();
        let (id, deadline): (String, i64) = db
            .query_row(
                "SELECT exchange_id,deadline_ms FROM collaboration_exchanges",
                [],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .unwrap();
        let id = Uuid::parse_str(&id).unwrap();
        let mut store = EngagementStore::open(&fixture.database()).unwrap();
        store
            .transact(|tx| {
                let permit = crate::scheduler::claim(
                    tx,
                    crate::assignment_queue::Owner::Managed(session),
                    target,
                    now_ms()?,
                )?
                .unwrap();
                crate::scheduler::prepare_dispatch(tx, &permit, now_ms()?)?;
                crate::collaboration::link_turn(
                    tx,
                    id,
                    target,
                    "native-thread",
                    "blocking-target",
                    1,
                )?;
                crate::scheduler::finish_dispatch(
                    tx,
                    &permit,
                    &MemberDispatchOutcome::Accepted {
                        turn_ref: "blocking-target".into(),
                    },
                    now_ms()?,
                )
            })
            .unwrap();
        let original_link: (String, String, String, u64) = store.connection().query_row(
            "SELECT target_run_id,thread_id,turn_id,generation FROM collaboration_execution_links WHERE exchange_id=?1",
            [id.to_string()], |r| Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?)),
        ).unwrap();
        assert_eq!(
            store
                .transact(|tx| crate::collaboration::link_turn(
                    tx,
                    id,
                    target,
                    "native-thread",
                    "conflicting-target",
                    1
                ))
                .unwrap_err()
                .code,
            "COLLABORATION_NOT_ALLOWED"
        );
        assert_eq!(store.connection().query_row(
            "SELECT target_run_id,thread_id,turn_id,generation FROM collaboration_execution_links WHERE exchange_id=?1",
            [id.to_string()], |r| Ok((r.get::<_,String>(0)?,r.get::<_,String>(1)?,r.get::<_,String>(2)?,r.get::<_,u64>(3)?)),
        ).unwrap(),original_link);
        assert_eq!(store.connection().query_row("SELECT count(*) FROM orchestration_events WHERE kind='collaboration_target_linked'",[],|r|r.get::<_,u64>(0)).unwrap(),1);
        // A linked acceptance wins even after the original effect bound.
        assert!(
            store
                .transact(|tx| crate::scheduler::reconcile_consultation_dispatch(
                    tx,
                    crate::scheduler::Actor {
                        owner: crate::assignment_queue::Owner::Managed(session),
                        run: target
                    },
                    deadline
                ))
                .unwrap()
                .is_none()
        );
        let terminal = crate::turn::TerminalTurn {
            thread_id: "native-thread".into(),
            turn_id: "blocking-target".into(),
            status: "completed".into(),
            effort: "low".into(),
            final_response: Some(crate::turn::FinalResponse::Inline {
                text: "The exact terminal answer.".into(),
            }),
            usage: None,
        };
        crate::collaboration::settle_target(&fixture.state_root, target, &terminal).unwrap();
        let receipt = pending.join().unwrap().unwrap();
        assert_eq!(
            receipt,
            json!({"operation":"submit_consultation_result","exchange_id":id,"target_run_id":target,"state":"queued"})
        );
        collaboration_wait_count(&fixture, 0);
        let started = std::time::Instant::now();
        assert_eq!(
            collaboration_call(&fixture, &ctx, &request).unwrap(),
            receipt
        );
        assert!(started.elapsed() < Duration::from_millis(500));
        assert_eq!(
            db.query_row("SELECT deadline_ms FROM collaboration_exchanges", [], |r| r
                .get::<_, i64>(0))
                .unwrap(),
            deadline
        );
        assert_eq!(
            db.query_row(
                "SELECT execution_state FROM collaboration_exchanges",
                [],
                |r| r.get::<_, String>(0)
            )
            .unwrap(),
            "succeeded"
        );
        assert_eq!(
            db.query_row(
                "SELECT count(*) FROM collaboration_execution_links",
                [],
                |r| r.get::<_, u64>(0)
            )
            .unwrap(),
            1
        );
    }

    fn collaboration_install_history(
        fixture: &Fixture,
        target: Uuid,
        records: &[crate::audit::AuditRecord],
    ) {
        let directory = crate::run::run_root(&fixture.state_root, target);
        let mut bytes = Vec::new();
        let mut projection = crate::projection::RunStateProjection::starting(target);
        for record in records {
            bytes.extend(record.canonical_line().unwrap());
            projection = crate::projection::project_next(target, &projection, record, |r| {
                Ok(r.sequence().to_string())
            })
            .unwrap();
        }
        fs::write(directory.join("audit.jsonl"), bytes).unwrap();
        fs::write(
            directory.join("state.json"),
            serde_json::to_vec(&projection).unwrap(),
        )
        .unwrap();
    }

    #[test]
    fn collaboration_reserved_dispatch_crash_classifies_unknown_at_original_effect_bound() {
        let (fixture, session, source, target, mut ctx, request) = collaboration_fixture();
        fixture.initialize_writer_authority();
        collaboration_captured_controller(&fixture, source);
        collaboration_captured_controller(&fixture, target);
        collaboration_observable_core(&fixture, source);
        collaboration_observable_core(&fixture, target);
        let receipt = collaboration_call(&fixture, &ctx, &request).unwrap();
        let id = Uuid::parse_str(receipt["exchange_id"].as_str().unwrap()).unwrap();
        let actor = crate::scheduler::Actor {
            owner: crate::assignment_queue::Owner::Managed(session),
            run: target,
        };
        let _lifecycle = crate::worker::RunLifecycleLease::acquire(
            &fixture.state_root,
            &fixture.view.workspace_id,
            target,
            1,
        )
        .unwrap();
        let mut store = EngagementStore::open(&fixture.database()).unwrap();
        let permit = store
            .transact(|tx| {
                let permit = crate::scheduler::claim(tx, actor.owner, target, now_ms()?)?.unwrap();
                crate::scheduler::prepare_dispatch(tx, &permit, now_ms()?)?;
                // Process loss here supplies no finish_dispatch outcome or acceptance.
                Ok(permit)
            })
            .unwrap();
        let deadline = crate::collaboration::execution_record(store.connection(), id)
            .unwrap()
            .deadline_ms;
        let lease: i64 = store
            .connection()
            .query_row(
                "SELECT lease_until_ms FROM scheduler_claims WHERE claim_id=?1",
                [permit.claim.to_string()],
                |r| r.get(0),
            )
            .unwrap();
        assert!(lease < deadline);
        // These are controlled observation-clock boundaries, not elapsed time.
        assert!(
            store
                .transact(|tx| crate::scheduler::reconcile_consultation_dispatch(tx, actor, lease))
                .unwrap()
                .is_none()
        );
        assert!(
            store
                .transact(|tx| crate::scheduler::reconcile_consultation_dispatch(
                    tx,
                    actor,
                    deadline - 1
                ))
                .unwrap()
                .is_none()
        );
        let foreign = crate::scheduler::Actor {
            owner: crate::assignment_queue::Owner::Managed(Uuid::now_v7()),
            run: target,
        };
        assert_eq!(
            store
                .transact(|tx| crate::scheduler::reconcile_consultation_dispatch(
                    tx, foreign, deadline
                ))
                .unwrap_err()
                .details["reason"],
            "consultation_claim_owner_changed"
        );
        for fault in ["outbox", "event"] {
            store.connection().execute_batch(if fault=="outbox" {
                "CREATE TRIGGER crash_unknown BEFORE INSERT ON collaboration_result_outbox BEGIN SELECT RAISE(ABORT,'outbox fault'); END;"
            } else {
                "CREATE TRIGGER crash_unknown BEFORE INSERT ON orchestration_events WHEN NEW.kind='scheduler_dispatch_observed' BEGIN SELECT RAISE(ABORT,'event fault'); END;"
            }).unwrap();
            assert!(
                store
                    .transact(|tx| crate::scheduler::reconcile_consultation_dispatch(
                        tx, actor, deadline
                    ))
                    .is_err()
            );
            assert_eq!(
                store
                    .connection()
                    .query_row("SELECT phase FROM scheduler_claims", [], |r| r
                        .get::<_, String>(0))
                    .unwrap(),
                "dispatching"
            );
            assert_eq!(
                store
                    .connection()
                    .query_row(
                        "SELECT execution_state FROM collaboration_exchanges",
                        [],
                        |r| r.get::<_, String>(0)
                    )
                    .unwrap(),
                "dispatching"
            );
            assert_eq!(
                store
                    .connection()
                    .query_row(
                        "SELECT count(*) FROM collaboration_result_outbox",
                        [],
                        |r| r.get::<_, u64>(0)
                    )
                    .unwrap(),
                0
            );
            assert_eq!(store.connection().query_row("SELECT count(*) FROM orchestration_events WHERE kind='scheduler_dispatch_observed'",[],|r|r.get::<_,u64>(0)).unwrap(),0);
            store
                .connection()
                .execute_batch("DROP TRIGGER crash_unknown")
                .unwrap();
        }
        ctx.source_tool_call_id = "wait-crashed-dispatch".into();
        let waiter = collaboration_spawn_call(
            fixture.state_root.clone(),
            ctx.clone(),
            json!({"operation":"await_consultations","exchange_ids":[id],"return_when":"all","transport_wait_seconds":5}),
        );
        collaboration_wait_count(&fixture, 1);
        assert_eq!(
            store
                .transact(|tx| crate::scheduler::reconcile_consultation_dispatch(
                    tx, actor, deadline
                ))
                .unwrap(),
            Some(source)
        );
        // The existing post-commit notifier wakes local waiters and central hints.
        crate::collaboration::notify_exchange(&fixture.state_root, id).unwrap();
        let waited = waiter.join().unwrap().unwrap();
        assert_eq!(
            waited["completed"][0]["execution_state"],
            "interrupted_unknown"
        );
        assert_eq!(
            waited["completed"][0]["safe_error_code"],
            "INTERRUPTED_UNKNOWN"
        );
        drop(store);
        let mut store = EngagementStore::open(&fixture.database()).unwrap();
        for _ in 0..2 {
            assert!(
                store
                    .transact(|tx| crate::scheduler::reconcile_consultation_dispatch(
                        tx,
                        actor,
                        deadline + 1
                    ))
                    .unwrap()
                    .is_none()
            );
        }
        assert_eq!(
            store
                .connection()
                .query_row(
                    "SELECT claim_id,phase,lease_until_ms FROM scheduler_claims",
                    [],
                    |r| Ok((
                        r.get::<_, String>(0)?,
                        r.get::<_, String>(1)?,
                        r.get::<_, i64>(2)?
                    ))
                )
                .unwrap(),
            (permit.claim.to_string(), "unknown".into(), lease)
        );
        assert_eq!(
            store
                .connection()
                .query_row(
                    "SELECT execution_state,deadline_ms FROM collaboration_exchanges",
                    [],
                    |r| Ok((r.get::<_, String>(0)?, r.get::<_, i64>(1)?))
                )
                .unwrap(),
            ("interrupted_unknown".into(), deadline)
        );
        for (table, expected) in [
            ("collaboration_results", 0),
            ("collaboration_execution_links", 0),
            ("collaboration_result_outbox", 1),
            ("collaboration_mailbox", 1),
        ] {
            assert_eq!(
                store
                    .connection()
                    .query_row(&format!("SELECT count(*) FROM {table}"), [], |r| r
                        .get::<_, u64>(0))
                    .unwrap(),
                expected
            );
        }
        assert_eq!(store.connection().query_row("SELECT count(*) FROM orchestration_events WHERE kind='scheduler_dispatch_observed'",[],|r|r.get::<_,u64>(0)).unwrap(),1);
        assert!(
            store
                .transact(|tx| crate::scheduler::claim(tx, actor.owner, target, deadline + 1))
                .unwrap()
                .is_none()
        );
        assert_eq!(
            crate::scheduler::idle_mail_guards(store.connection(), actor)
                .unwrap_err()
                .details["reason"],
            "actor_has_claim"
        );
        let snapshot = crate::snapshot::RunSnapshot::load(&fixture.state_root, target, 0).unwrap();
        store
            .transact(|tx| {
                crate::scheduler::reconcile_claim(
                    tx,
                    actor,
                    &snapshot,
                    deadline + 1,
                    &fixture.state_root,
                )
            })
            .unwrap();
        assert_eq!(
            store
                .connection()
                .query_row("SELECT count(*) FROM scheduler_claims", [], |r| r
                    .get::<_, u64>(0))
                .unwrap(),
            1
        );
        assert!(
            !snapshot
                .observed_ledger(&fixture.state_root)
                .unwrap()
                .records()
                .iter()
                .any(|r| r.kind() == crate::audit::AuditKind::TurnStarted)
        );
        ctx.source_tool_call_id = "collect-crashed-dispatch".into();
        let collect = json!({"operation":"collect_collaboration_results","limit":1});
        let unknown = collaboration_call(&fixture, &ctx, &collect).unwrap();
        assert_eq!(
            unknown["results"][0]["execution_state"],
            "interrupted_unknown"
        );
        assert!(unknown["results"][0]["result_artifact_ref"].is_null());
        assert_eq!(
            collaboration_call(&fixture, &ctx, &collect).unwrap(),
            unknown
        );
        assert_eq!(
            collaboration_call(
                &fixture,
                &crate::orchestration::PrimaryCallContext {
                    source_tool_call_id: "native-call".into(),
                    ..ctx
                },
                &request
            )
            .unwrap(),
            receipt
        );
    }

    #[test]
    fn collaboration_unknown_dispatch_recovers_only_original_submit_history_after_deadline() {
        let (fixture, session, source, target, mut ctx, mut request) = collaboration_fixture();
        fixture.initialize_writer_authority();
        collaboration_captured_controller(&fixture, source);
        collaboration_captured_controller(&fixture, target);
        collaboration_observable_core(&fixture, source);
        collaboration_observable_core(&fixture, target);
        request["deadline_seconds"] = json!(2);
        ctx.source_tool_call_id = "unknown-dispatch".into();
        let receipt = collaboration_call(&fixture, &ctx, &request).unwrap();
        let id = Uuid::parse_str(receipt["exchange_id"].as_str().unwrap()).unwrap();
        let mut store = EngagementStore::open(&fixture.database()).unwrap();
        let permit = store
            .transact(|tx| {
                let permit = crate::scheduler::claim(
                    tx,
                    crate::assignment_queue::Owner::Managed(session),
                    target,
                    now_ms()?,
                )?
                .unwrap();
                crate::scheduler::prepare_dispatch(tx, &permit, now_ms()?)?;
                crate::scheduler::finish_dispatch(
                    tx,
                    &permit,
                    &MemberDispatchOutcome::Uncertain {
                        code: "RECOVERY_REQUIRED".into(),
                        message: "lost reply".into(),
                    },
                    now_ms()?,
                )?;
                Ok(permit)
            })
            .unwrap();
        crate::collaboration::reconcile_target(&fixture.state_root, target).unwrap();
        assert_eq!(
            store
                .connection()
                .query_row(
                    "SELECT execution_state FROM collaboration_exchanges",
                    [],
                    |r| r.get::<_, String>(0)
                )
                .unwrap(),
            "interrupted_unknown"
        );
        assert_eq!(
            store
                .connection()
                .query_row(
                    "SELECT count(*) FROM collaboration_execution_links",
                    [],
                    |r| r.get::<_, u64>(0)
                )
                .unwrap(),
            0
        );
        let snapshot = crate::snapshot::RunSnapshot::load(&fixture.state_root, target, 0).unwrap();
        store
            .transact(|tx| {
                crate::scheduler::reconcile_claim(
                    tx,
                    crate::scheduler::Actor {
                        owner: crate::assignment_queue::Owner::Managed(session),
                        run: target,
                    },
                    &snapshot,
                    now_ms()? + 60_000,
                    &fixture.state_root,
                )
            })
            .unwrap();
        assert_eq!(
            store
                .connection()
                .query_row("SELECT phase FROM scheduler_claims", [], |r| r
                    .get::<_, String>(0))
                .unwrap(),
            "unknown"
        );
        ctx.source_tool_call_id = "collect-original-unknown".into();
        let collect = json!({"operation":"collect_collaboration_results","limit":1});
        let original_unknown = collaboration_call(&fixture, &ctx, &collect).unwrap();
        assert_eq!(
            original_unknown["results"][0]["execution_state"],
            "interrupted_unknown"
        );
        let manifest = crate::run::RunStore::new(
            crate::workspace::SystemWorkspacePlatform,
            &fixture.state_root,
        )
        .load_manifest(target)
        .unwrap();
        let record = crate::collaboration::execution_record(store.connection(), id).unwrap();
        let original_deadline = record.deadline_ms;
        let submit = crate::turn::TurnRequest {
            write: false,
            idempotency_key: format!("collaboration-exchange:{id}"),
            message: record.prompt,
            images: Vec::new(),
            model: manifest.model.clone(),
            effort: None,
            delivery: crate::turn::DeliveryMode::Submit,
        };
        let mut foreign = manifest.controller.identity.clone();
        foreign.controller_id = Uuid::now_v7();
        let (_, wrong) = crate::turn::tests::collaboration_submit_history(
            target,
            foreign,
            &fixture.view.workspace_id,
            submit.clone(),
        );
        let prefix = wrong
            .iter()
            .position(|r| r.kind() == crate::audit::AuditKind::TurnTerminal)
            .unwrap();
        collaboration_install_history(&fixture, target, &wrong[..prefix]);
        assert_eq!(
            crate::collaboration::reconcile_target(&fixture.state_root, target)
                .unwrap_err()
                .code,
            "COLLABORATION_NOT_ALLOWED"
        );
        assert_eq!(
            store
                .connection()
                .query_row(
                    "SELECT count(*) FROM collaboration_execution_links",
                    [],
                    |r| r.get::<_, u64>(0)
                )
                .unwrap(),
            0
        );
        let (accepted, records) = crate::turn::tests::collaboration_submit_history(
            target,
            manifest.controller.identity.clone(),
            &fixture.view.workspace_id,
            submit,
        );
        let prefix = records
            .iter()
            .position(|r| r.kind() == crate::audit::AuditKind::TurnTerminal)
            .unwrap();
        collaboration_install_history(&fixture, target, &records[..prefix]);
        std::thread::sleep(Duration::from_millis(2100));
        assert!(now_ms().unwrap() >= original_deadline);
        crate::collaboration::reconcile_target(&fixture.state_root, target).unwrap();
        assert_eq!(
            store
                .connection()
                .query_row(
                    "SELECT turn_id FROM collaboration_execution_links",
                    [],
                    |r| r.get::<_, String>(0)
                )
                .unwrap(),
            accepted.turn_id
        );
        assert_eq!(
            store
                .connection()
                .query_row(
                    "SELECT phase FROM scheduler_claims WHERE claim_id=?1",
                    [permit.claim.to_string()],
                    |r| r.get::<_, String>(0)
                )
                .unwrap(),
            "accepted"
        );
        assert_eq!(
            store
                .connection()
                .query_row("SELECT deadline_ms FROM collaboration_exchanges", [], |r| r
                    .get::<_, i64>(0))
                .unwrap(),
            original_deadline
        );
        assert_eq!(
            store
                .connection()
                .query_row("SELECT count(*) FROM collaboration_results", [], |r| r
                    .get::<_, u64>(0))
                .unwrap(),
            0
        );
        collaboration_install_history(&fixture, target, &records);
        crate::collaboration::reconcile_target(&fixture.state_root, target).unwrap();
        crate::collaboration::reconcile_target(&fixture.state_root, target).unwrap();
        assert_eq!(
            store
                .connection()
                .query_row(
                    "SELECT execution_state FROM collaboration_exchanges",
                    [],
                    |r| r.get::<_, String>(0)
                )
                .unwrap(),
            "succeeded"
        );
        assert_eq!(
            store
                .connection()
                .query_row(
                    "SELECT count(*) FROM collaboration_result_outbox",
                    [],
                    |r| r.get::<_, u64>(0)
                )
                .unwrap(),
            1
        );
        assert_eq!(store.connection().query_row("SELECT count(*) FROM orchestration_events WHERE kind='collaboration_result_published'",[],|r|r.get::<_,u64>(0)).unwrap(),1);
        assert_eq!(
            collaboration_call(&fixture, &ctx, &collect).unwrap(),
            original_unknown
        );
        ctx.source_tool_call_id = "collect-late-original-terminal".into();
        assert_eq!(
            collaboration_call(&fixture, &ctx, &collect).unwrap()["results"][0]["execution_state"],
            "succeeded"
        );
        assert_eq!(
            records
                .iter()
                .filter(|r| r.kind() == crate::audit::AuditKind::TurnStarted)
                .count(),
            1
        );
    }

    #[test]
    fn collaboration_publication_respects_retained_source_artifact_quota() {
        use std::os::unix::fs::OpenOptionsExt as _;
        let (fixture, session, source, target, mut ctx, request) = collaboration_fixture();
        fixture.initialize_writer_authority();
        let (_, terminal) = collaboration_accept(
            &fixture,
            session,
            source,
            target,
            &mut ctx,
            &request,
            "quota-result",
        );
        let directory = crate::run::run_root(&fixture.state_root, source).join("artifacts");
        fs::create_dir_all(&directory).unwrap();
        fs::set_permissions(&directory, fs::Permissions::from_mode(0o700)).unwrap();
        let mut retained = Vec::new();
        for _ in 0..8 {
            let path = directory.join(format!("{}.bin", Uuid::now_v7()));
            fs::OpenOptions::new()
                .create_new(true)
                .write(true)
                .mode(0o600)
                .open(&path)
                .unwrap()
                .set_len(32 * 1024 * 1024)
                .unwrap();
            retained.push(path);
        }
        assert_eq!(
            crate::artifact::logical_artifact_bytes(&directory).unwrap(),
            crate::artifact::MAX_RUN_ARTIFACT_BYTES
        );
        assert_eq!(
            crate::collaboration::settle_target(&fixture.state_root, target, &terminal)
                .unwrap_err()
                .code,
            "COLLABORATION_MAILBOX_FULL"
        );
        let db = rusqlite::Connection::open(fixture.database()).unwrap();
        assert_eq!(
            db.query_row(
                "SELECT execution_state FROM collaboration_exchanges",
                [],
                |r| r.get::<_, String>(0)
            )
            .unwrap(),
            "running"
        );
        assert_eq!(
            db.query_row("SELECT count(*) FROM collaboration_results", [], |r| r
                .get::<_, u64>(0))
                .unwrap(),
            0
        );
        fs::remove_file(retained.pop().unwrap()).unwrap();
        crate::collaboration::settle_target(&fixture.state_root, target, &terminal).unwrap();
        let logical = crate::artifact::logical_artifact_bytes(&directory).unwrap();
        assert!(
            logical > 7 * 32 * 1024 * 1024 && logical <= crate::artifact::MAX_RUN_ARTIFACT_BYTES
        );
    }

    #[test]
    fn collaboration_replay_and_artifact_metadata_require_original_causal_binding() {
        for case in 0..5 {
            let (fixture, session, source, target, mut ctx, request) = collaboration_fixture();
            fixture.initialize_writer_authority();
            let (_, terminal) = collaboration_accept(
                &fixture,
                session,
                source,
                target,
                &mut ctx,
                &request,
                "bound-result",
            );
            crate::collaboration::settle_target(&fixture.state_root, target, &terminal).unwrap();
            ctx.source_tool_call_id = "bound-collect".into();
            let payload = json!({"operation":"collect_collaboration_results","limit":1});
            let db = rusqlite::Connection::open(fixture.database()).unwrap();
            if case < 2 {
                let original = collaboration_call(&fixture, &ctx, &payload).unwrap();
                assert_eq!(
                    collaboration_call(&fixture, &ctx, &payload).unwrap(),
                    original
                );
                let changed =
                    json!({"operation":"collect_collaboration_results_result","results":[]})
                        .to_string();
                db.execute("UPDATE collaboration_tool_receipts SET response_json=?1 WHERE call_id='bound-collect'", [&changed]).unwrap();
                if case == 1 {
                    db.execute("UPDATE collaboration_tool_receipts SET response_sha256=?1 WHERE call_id='bound-collect'", [crate::jcs::sha256_hex(changed.as_bytes())]).unwrap();
                }
            } else {
                match case {
                    2 => {
                        db.execute(
                            "UPDATE collaboration_results SET artifact_id=?1",
                            [Uuid::now_v7().to_string()],
                        )
                        .unwrap();
                    }
                    3 => {
                        db.execute(
                            "UPDATE collaboration_results SET byte_length=byte_length+1",
                            [],
                        )
                        .unwrap();
                    }
                    _ => {
                        db.execute("UPDATE collaboration_results SET safe_error_code='private runtime details'", []).unwrap();
                    }
                }
            }
            let error = collaboration_call(&fixture, &ctx, &payload).unwrap_err();
            let safe = crate::collaboration::error_result(&error);
            assert!(!safe.to_string().contains("private runtime details"));
            assert!(
                !safe
                    .to_string()
                    .contains(fixture.state_root.to_str().unwrap())
            );
            if case >= 2 {
                assert_eq!(
                    db.query_row(
                        "SELECT delivery_state FROM collaboration_exchanges",
                        [],
                        |r| r.get::<_, String>(0)
                    )
                    .unwrap(),
                    "pending"
                );
                assert_eq!(db.query_row("SELECT count(*) FROM collaboration_tool_receipts WHERE call_id='bound-collect'", [], |r|r.get::<_,u64>(0)).unwrap(), 0);
            }
        }
    }

    #[test]
    fn collaboration_missing_invalid_private_and_corrupt_results_never_fabricate_success() {
        for case in 0..15 {
            let (fixture, session, source, target, mut ctx, request) = collaboration_fixture();
            fixture.initialize_writer_authority();
            let (id, mut terminal) = collaboration_accept(
                &fixture,
                session,
                source,
                target,
                &mut ctx,
                &request,
                "unreadable-result",
            );
            let artifact = Uuid::now_v7();
            let directory = crate::run::run_root(&fixture.state_root, target).join("artifacts");
            fs::create_dir_all(&directory).unwrap();
            fs::set_permissions(&directory, fs::Permissions::from_mode(0o700)).unwrap();
            terminal.final_response = match case {
                0 => None,
                1 => Some(crate::turn::FinalResponse::Artifact {
                    artifact_id: artifact,
                    byte_length: 4,
                    sha256: crate::jcs::sha256_hex(b"body"),
                    created_at: "2026-10-30T00:00:00Z".into(),
                }),
                2 => {
                    fs::write(directory.join(format!("{artifact}.bin")), b"wrong").unwrap();
                    Some(crate::turn::FinalResponse::Artifact {
                        artifact_id: artifact,
                        byte_length: 5,
                        sha256: crate::jcs::sha256_hex(b"right"),
                        created_at: "2026-10-30T00:00:00Z".into(),
                    })
                }
                3 => Some(crate::turn::FinalResponse::Artifact {
                    artifact_id: artifact,
                    byte_length: crate::turn::MAX_FINAL_RESPONSE_ARTIFACT_BYTES as u64 + 1,
                    sha256: "a".repeat(64),
                    created_at: "2026-10-30T00:00:00Z".into(),
                }),
                4 => Some(crate::turn::FinalResponse::Inline {
                    text: format!("private runtime {}", fixture.state_root.display()),
                }),
                5..=7 => Some(crate::turn::FinalResponse::Inline {
                    text: [
                        ".dolgorae/private",
                        "controller-capability",
                        "\"jsonrpc\":\"2.0\"",
                    ][case - 5]
                        .into(),
                }),
                8 | 9 => {
                    let path = directory.join(format!("{artifact}.bin"));
                    if case == 8 {
                        let original = directory.join("symlink-body");
                        fs::write(&original, b"body").unwrap();
                        std::os::unix::fs::symlink(original, &path).unwrap();
                    } else {
                        fs::write(&path, b"body plus unreported bytes").unwrap();
                    }
                    Some(crate::turn::FinalResponse::Artifact {
                        artifact_id: artifact,
                        byte_length: 4,
                        sha256: crate::jcs::sha256_hex(b"body"),
                        created_at: "2026-10-30T00:00:00Z".into(),
                    })
                }
                10 => Some(crate::turn::FinalResponse::Inline {
                    text: "api_key=private-result-canary".into(),
                }),
                11..=14 => Some(crate::turn::FinalResponse::Inline {
                    text: format!(
                        "-----BEGIN {} PRIVATE KEY-----\nY2FuYXJ5\n-----END {} PRIVATE KEY-----",
                        ["EC", "DSA", "OPENSSH", "ENCRYPTED"][case - 11],
                        ["EC", "DSA", "OPENSSH", "ENCRYPTED"][case - 11]
                    ),
                }),
                _ => unreachable!(),
            };
            crate::collaboration::settle_target(&fixture.state_root, target, &terminal).unwrap();
            ctx.source_tool_call_id = "await-unavailable".into();
            let awaited = collaboration_call(&fixture, &ctx, &json!({
                "operation":"await_consultations", "exchange_ids":[id],"return_when":"all","transport_wait_seconds":1
            })).unwrap();
            assert_eq!(awaited["completed"][0]["execution_state"], "failed");
            assert_eq!(collaboration_call(&fixture, &ctx, &json!({
                "operation":"await_consultations", "exchange_ids":[id],"return_when":"all","transport_wait_seconds":1
            })).unwrap(), awaited);
            ctx.source_tool_call_id = "read-unavailable".into();
            let error = collaboration_call(
                &fixture,
                &ctx,
                &json!({
                    "operation":"read_collaboration_result","exchange_id":id,"offset":0,"limit":3
                }),
            )
            .unwrap_err();
            assert!(!error.retryable);
            let repeated = collaboration_call(&fixture, &ctx, &json!({"operation":"read_collaboration_result","exchange_id":id,"offset":0,"limit":3})).unwrap_err();
            assert_eq!(repeated.code, error.code);
            assert!(!repeated.retryable);
            let projected = crate::collaboration::error_result(&error);
            assert_eq!(
                projected["message"],
                "This consultation operation is unavailable in this runtime."
            );
            let db = rusqlite::Connection::open(fixture.database()).unwrap();
            assert_eq!(db.query_row("SELECT count(*) FROM collaboration_results WHERE exchange_id=?1 AND (artifact_id IS NOT NULL OR sha256 IS NOT NULL)", [id.to_string()], |r| r.get::<_,u64>(0)).unwrap(),0);
            ctx.source_tool_call_id = "collect-unavailable".into();
            let response = collaboration_call(
                &fixture,
                &ctx,
                &json!({"operation":"collect_collaboration_results","limit":1}),
            )
            .unwrap();
            assert_eq!(
                collaboration_call(
                    &fixture,
                    &ctx,
                    &json!({"operation":"collect_collaboration_results","limit":1})
                )
                .unwrap(),
                response
            );
            assert_eq!(response["results"][0]["exchange_id"], id.to_string());
            assert_eq!(response["results"][0]["execution_state"], "failed");
            assert!(response["results"][0]["result_artifact_ref"].is_null());
            assert_eq!(
                response["results"][0]["safe_error_code"],
                "COLLABORATION_TRANSPORT_UNAVAILABLE"
            );
            for marker in [
                ".dolgorae/",
                "controller-capability",
                "jsonrpc",
                "unreported bytes",
                "symlink-body",
                "private-result-canary",
                "PRIVATE KEY",
                "Y2FuYXJ5",
            ] {
                assert!(!response.to_string().contains(marker));
            }
            assert!(
                !response
                    .to_string()
                    .contains(fixture.state_root.to_str().unwrap())
            );
        }
        let (fixture, session, source, target, mut ctx, request) = collaboration_fixture();
        fixture.initialize_writer_authority();
        let (id, terminal) = collaboration_accept(
            &fixture,
            session,
            source,
            target,
            &mut ctx,
            &request,
            "corrupt-result",
        );
        crate::collaboration::settle_target(&fixture.state_root, target, &terminal).unwrap();
        let db = rusqlite::Connection::open(fixture.database()).unwrap();
        db.execute("UPDATE result_content SET bytes=?1 WHERE sha256=(SELECT sha256 FROM collaboration_results WHERE exchange_id=?2)",rusqlite::params![b"corrupt".to_vec(),id.to_string()]).unwrap();
        ctx.source_tool_call_id = "corrupt-collect".into();
        let error = collaboration_call(
            &fixture,
            &ctx,
            &json!({"operation":"collect_collaboration_results","limit":1}),
        )
        .unwrap_err();
        let safe = crate::collaboration::error_result(&error);
        assert_eq!(safe["operation"], "collaboration_error");
        assert!(
            !safe
                .to_string()
                .contains(fixture.state_root.to_str().unwrap())
        );
        assert_eq!(
            db.query_row(
                "SELECT delivery_state FROM collaboration_exchanges",
                [],
                |r| r.get::<_, String>(0)
            )
            .unwrap(),
            "pending"
        );
        assert_eq!(
            db.query_row(
                "SELECT count(*) FROM collaboration_tool_receipts WHERE call_id='corrupt-collect'",
                [],
                |r| r.get::<_, u64>(0)
            )
            .unwrap(),
            0
        );
    }
    #[test]
    fn research_group_public_managed_origin_replay_and_observation_require_real_controller() {
        let mut f = Fixture::new();
        let home = DolgoraeHome::from_canonical_home(f.root.clone()).unwrap();
        let state = home.workspace_root(&f.view.workspace_id);
        fs::create_dir_all(state.parent().unwrap()).unwrap();
        fs::set_permissions(state.parent().unwrap(), fs::Permissions::from_mode(0o700)).unwrap();
        fs::rename(&f.state_root, &state).unwrap();
        f.state_root = state;
        f.initialize_writer_authority();
        let credential_path = f.root.join("group-controller.json");
        let created = crate::controller::create_controller_credential(
            &credential_path,
            ControllerKind::Automation,
            "group-test".into(),
            Some("owner".into()),
            None,
        )
        .unwrap();
        let carrier = crate::controller::CredentialCarrier::open_path(&credential_path).unwrap();
        f.controller =
            crate::controller::binding_from_credential(&created.credential, 1, &carrier).unwrap();
        let session = f.managed_session();
        let installed = f.install();
        let snapshot =
            crate::provisioning::retained_snapshot(&f.state_root, &installed.provisioning_ref)
                .unwrap();
        let (_, configuration) = snapshot.admitted_configuration().unwrap();
        let root = f.view.canonical_path.to_path_buf().unwrap();
        let mut entries = Vec::new();
        let mut inputs = Vec::new();
        for index in 0..2 {
            let mut task = fixture_task();
            task.brief = format!("Research managed question {index}");
            let (accepted, _) = crate::successor_capture::capture_facade_task(
                &configuration,
                &task,
                "read_only",
                None,
            )
            .unwrap();
            let body = json!({"schema":"dolgorae.group-task-input/v1","provisioning_ref":installed.provisioning_ref,"assignment":{"task_body":task,"accepted_task_identity":accepted,"deadline_seconds":30}});
            let bytes = crate::operation::canonical(&body).unwrap();
            let path = root.join(format!("managed-input-{index}.json"));
            fs::write(&path, &bytes).unwrap();
            entries.push(json!({"entry_key":format!("entry-{index}"),"role_snapshot_digest":installed.role_snapshot_digest,"agent_configuration_digest":installed.agent_configuration_digest,"accepted_task_digest":accepted.digest().unwrap()}));
            inputs.push(json!({"entry_key":format!("entry-{index}"),"absolute_file_path":path,"content":crate::delegation_identity::BytesRef::from_bytes(&bytes)}));
        }
        let request = json!({"schema":"dolgorae.external-specialist-request/v5","operation":"assign_group","scope_kind":"orchestrated_session","scope_ref":session,"idempotency_key":"public-group","expected_revision":null,"manifest":{"schema":"dolgorae.group-assignment/v1","scope_kind":"orchestrated_session","scope_ref":session,"entries":entries},"inputs":inputs});
        let port = FakePort::new();
        let assigned = research_group::public_call(
            &home,
            &f.view,
            &carrier,
            Some(session),
            "orchestrated_session",
            session,
            "assign_group",
            Some("public-group"),
            None,
            &request,
            &port,
        )
        .unwrap();
        assert_eq!(assigned["exact_replay"], false);
        assert_eq!(port.starts.borrow().len(), 1);
        assert_eq!(
            f.assignment_rows(),
            0,
            "standalone group creates no Podway caller scope or round"
        );
        let group = assigned["response"]["group_ref"].as_str().unwrap();
        let lookup = research_group::public_lookup(
            &f.state_root,
            &f.view.workspace_id,
            &carrier,
            "orchestrated_session",
            session,
            "assign_group",
            "public-group",
        )
        .unwrap();
        assert_eq!(lookup["state"], "accepted");
        let store = EngagementStore::open_read_only(&f.database()).unwrap();
        let tasks:Vec<(String,String,String,String)>=store.connection().prepare("SELECT task_id,target_run_id,source_turn_id,source_tool_call_id FROM brokered_tasks ORDER BY task_id").unwrap().query_map([],|row|Ok((row.get(0)?,row.get(1)?,row.get(2)?,row.get(3)?))).unwrap().collect::<Result<_,_>>().unwrap();
        assert_eq!(tasks.len(), 2);
        assert!(
            tasks
                .iter()
                .all(|(_, _, turn, call)| turn.is_empty() && call.is_empty()),
            "public origin records actual absence of native calls"
        );
        drop(store);
        for (task, member, _, _) in &tasks {
            retained_managed_recovery(
                &f.scope(),
                session,
                Uuid::parse_str(member).unwrap(),
                Uuid::parse_str(task).unwrap(),
            )
            .unwrap();
        }
        for index in 0..2 {
            fs::remove_file(root.join(format!("managed-input-{index}.json"))).unwrap();
        }
        let replay = research_group::public_call(
            &home,
            &f.view,
            &carrier,
            Some(session),
            "orchestrated_session",
            session,
            "assign_group",
            Some("public-group"),
            None,
            &request,
            &port,
        )
        .unwrap();
        assert_eq!(replay["exact_replay"], true);
        assert_eq!(
            replay["response"]["receipt"],
            assigned["response"]["receipt"]
        );
        assert_eq!(port.starts.borrow().len(), 1);
        let mut read = json!({"operation":"collect_group","scope_kind":"orchestrated_session","scope_ref":session,"group_ref":group,"cursor":null,"limit":1});
        let page = research_group::public_call(
            &home,
            &f.view,
            &carrier,
            Some(session),
            "orchestrated_session",
            session,
            "collect_group",
            None,
            None,
            &read,
            &port,
        )
        .unwrap();
        assert_eq!(
            page["response"]["coverage"]["sources"]
                .as_array()
                .unwrap()
                .len(),
            1
        );
        read["cursor"] = page["response"]["coverage"]["next_cursor"].clone();
        let last = research_group::public_call(
            &home,
            &f.view,
            &carrier,
            Some(session),
            "orchestrated_session",
            session,
            "collect_group",
            None,
            None,
            &read,
            &port,
        )
        .unwrap();
        assert!(last["response"]["coverage"]["next_cursor"].is_null());
        let wait = json!({"operation":"await_group","scope_kind":"orchestrated_session","scope_ref":session,"group_ref":group,"predicate":{"kind":"k","k":2},"timeout_ms":0});
        let waited = research_group::public_call(
            &home,
            &f.view,
            &carrier,
            Some(session),
            "orchestrated_session",
            session,
            "await_group",
            None,
            None,
            &wait,
            &port,
        )
        .unwrap();
        assert_eq!(waited["response"]["predicate_satisfied"], false);
        assert_eq!(waited["response"]["wait_timed_out"], true);
        assert_eq!(
            port.dispatched.borrow().len(),
            0,
            "all R methods preserve queued work"
        );
        let other_path = f.root.join("foreign-controller.json");
        crate::controller::create_controller_credential(
            &other_path,
            ControllerKind::Automation,
            "foreign".into(),
            None,
            None,
        )
        .unwrap();
        let foreign = crate::controller::CredentialCarrier::open_path(&other_path).unwrap();
        assert!(
            research_group::public_lookup(
                &f.state_root,
                &f.view.workspace_id,
                &foreign,
                "orchestrated_session",
                session,
                "assign_group",
                "public-group"
            )
            .is_err()
        );
    }

    #[test]
    fn research_group_external_recovery_checks_retained_origin_and_current_controller() {
        let mut f = Fixture::new();
        let home = DolgoraeHome::from_canonical_home(f.root.clone()).unwrap();
        let state = home.workspace_root(&f.view.workspace_id);
        fs::create_dir_all(state.parent().unwrap()).unwrap();
        fs::set_permissions(state.parent().unwrap(), fs::Permissions::from_mode(0o700)).unwrap();
        fs::rename(&f.state_root, &state).unwrap();
        f.state_root = state;
        f.initialize_writer_authority();
        let credential = f.root.join("recovery-controller.json");
        let created = crate::controller::create_controller_credential(
            &credential,
            ControllerKind::Automation,
            "recovery-owner".into(),
            None,
            None,
        )
        .unwrap();
        let carrier = crate::controller::CredentialCarrier::open_path(&credential).unwrap();
        f.controller =
            crate::controller::binding_from_credential(&created.credential, 1, &carrier).unwrap();
        f.set_up_namespace();
        let engagement = f.open();
        let installed = f.install();
        let snapshot =
            crate::provisioning::retained_snapshot(&f.state_root, &installed.provisioning_ref)
                .unwrap();
        let (_, configuration) = snapshot.admitted_configuration().unwrap();
        let task = fixture_task();
        let (accepted, _) =
            crate::successor_capture::capture_facade_task(&configuration, &task, "read_only", None)
                .unwrap();
        let input = json!({"schema":"dolgorae.group-task-input/v1","provisioning_ref":installed.provisioning_ref,"assignment":{"task_body":task,"accepted_task_identity":accepted,"deadline_seconds":30}});
        let bytes = crate::operation::canonical(&input).unwrap();
        let path = f
            .view
            .canonical_path
            .to_path_buf()
            .unwrap()
            .join("recovery-input.json");
        fs::write(&path, &bytes).unwrap();
        let request = json!({"schema":"dolgorae.external-specialist-request/v5","operation":"assign_group","scope_kind":"external_engagement","scope_ref":engagement,"idempotency_key":"recover-group","expected_revision":null,"manifest":{"schema":"dolgorae.group-assignment/v1","scope_kind":"external_engagement","scope_ref":engagement,"entries":[{"entry_key":"entry","role_snapshot_digest":installed.role_snapshot_digest,"agent_configuration_digest":installed.agent_configuration_digest,"accepted_task_digest":accepted.digest().unwrap()}]},"inputs":[{"entry_key":"entry","absolute_file_path":path,"content":crate::delegation_identity::BytesRef::from_bytes(&bytes)}]});
        let port = FakePort::new();
        research_group::public_call(
            &home,
            &f.view,
            &carrier,
            None,
            "external_engagement",
            engagement,
            "assign_group",
            Some("recover-group"),
            None,
            &request,
            &port,
        )
        .unwrap();
        let store = EngagementStore::open_read_only(&f.database()).unwrap();
        let (task, member): (String, String) = store
            .connection()
            .query_row("SELECT task_id,specialist_run_id FROM tasks", [], |row| {
                Ok((row.get(0)?, row.get(1)?))
            })
            .unwrap();
        let task = Uuid::parse_str(&task).unwrap();
        let member = Uuid::parse_str(&member).unwrap();
        let manifest = f.publish_external_member_manifest(engagement, member);
        let authorize = |carrier, task, manifest| {
            research_group::authorize_external_recovery(
                &f.state_root,
                &f.view,
                carrier,
                engagement,
                member,
                task,
                manifest,
            )
        };
        assert!(authorize(&carrier, task, &manifest).unwrap());
        // The native owner guard remains strict; this accepted group is not a
        // native Turn/tool invocation and must use its own retained proof.
        assert!(
            store
                .authorize_external_owner(
                    &f.view.workspace_id,
                    engagement,
                    "run.reconcile",
                    &carrier
                )
                .is_err()
        );
        assert!(!authorize(&carrier, Uuid::now_v7(), &manifest).unwrap());
        let other = f.root.join("foreign-recovery-controller.json");
        crate::controller::create_controller_credential(
            &other,
            ControllerKind::Automation,
            "foreign".into(),
            None,
            None,
        )
        .unwrap();
        let foreign = crate::controller::CredentialCarrier::open_path(&other).unwrap();
        assert!(authorize(&foreign, task, &manifest).is_err());
        let mut changed = manifest.clone();
        changed.agent_configuration.model = "foreign".into();
        assert!(authorize(&carrier, task, &changed).is_err());
        // Exercise the actual production port: successful origin authorization
        // reaches the independent native-ledger fence, not the legacy guard.
        let actual = crate::semantic::SemanticRunSettlementPort { carrier: &carrier };
        let error = actual
            .reconcile_member_task(MemberTaskSettlement {
                view: &f.view,
                state_root: &f.state_root,
                owner: SettlementOwner::External {
                    engagement_id: engagement,
                },
                member_ref: member,
                task_ref: task,
                execution_intent: "read_only",
            })
            .unwrap_err();
        assert!(!error.message.contains("external provenance"), "{error:?}");
        let mut writer = EngagementStore::open(&f.database()).unwrap();
        let origin = crate::storage_observation::read_content(
            store.connection(),
            "controller_group_task",
            &task.to_string(),
            "origin",
        )
        .unwrap()
        .unwrap();
        writer.transact(|tx|{tx.execute("DELETE FROM result_content_refs WHERE owner_kind='controller_group_task' AND owner_id=?1 AND representation='origin'",[task.to_string()]).unwrap();Ok(())}).unwrap();
        assert!(!authorize(&carrier, task, &manifest).unwrap());
        let missing = actual
            .reconcile_member_task(MemberTaskSettlement {
                view: &f.view,
                state_root: &f.state_root,
                owner: SettlementOwner::External {
                    engagement_id: engagement,
                },
                member_ref: member,
                task_ref: task,
                execution_intent: "read_only",
            })
            .unwrap_err();
        assert_eq!(
            missing.details["invariant"], "external provenance is missing",
            "missing group proof must not relax native provenance"
        );
        let mut invalid: Value = serde_json::from_slice(&origin).unwrap();
        invalid["member_ref"] = json!(Uuid::now_v7());
        writer
            .transact(|tx| {
                crate::storage_observation::put_content(
                    tx,
                    "controller_group_task",
                    &task.to_string(),
                    "origin",
                    &crate::operation::canonical(&invalid).unwrap(),
                )
                .map(|_| ())
            })
            .unwrap();
        assert!(
            authorize(&carrier, task, &manifest).is_err(),
            "foreign group origin cannot authorize native history"
        );
        writer.transact(|tx|{tx.execute("DELETE FROM result_content_refs WHERE owner_kind='controller_group_task' AND owner_id=?1 AND representation='origin'",[task.to_string()]).unwrap();crate::storage_observation::put_content(tx,"controller_group_task",&task.to_string(),"origin",&origin).map(|_|())}).unwrap();
        writer.transact(|tx|{tx.execute("UPDATE delegation_operations SET accepted_subjects_json='{}' WHERE operation_kind='assign_external_specialist_task'",[]).unwrap();Ok(())}).unwrap();
        assert!(
            authorize(&carrier, task, &manifest).is_err(),
            "original assignment receipt cannot be substituted"
        );
        assert!(port.dispatched.borrow().is_empty());
    }

    #[test]
    fn research_group_capture_replay_and_failure_coverage_are_durable() {
        let f = Fixture::new();
        f.set_up_namespace();
        let installed = f.install();
        let engagement = f.open();
        let port = FakePort::new();
        let caller = crate::caller_scope::fixture(4);
        let snapshot =
            crate::provisioning::retained_snapshot(&f.state_root, &installed.provisioning_ref)
                .unwrap();
        let (_, configuration) = snapshot.admitted_configuration().unwrap();
        let root = f.view.canonical_path.to_path_buf().unwrap();
        let mut entries = Vec::new();
        let mut inputs = Vec::new();
        for n in 0..2 {
            let mut task = fixture_task();
            task.brief = format!("Research question {n}");
            let (accepted, _) = crate::successor_capture::capture_facade_task(
                &configuration,
                &task,
                "read_only",
                None,
            )
            .unwrap();
            let input = json!({"schema":"dolgorae.group-task-input/v1", "provisioning_ref":installed.provisioning_ref, "assignment":{"task_body":task,"accepted_task_identity":accepted,"deadline_seconds":30}});
            assert!(
                crate::specialist_facade::validates(&input, "group_task_input"),
                "group input schema: {input}"
            );
            let bytes = crate::operation::canonical(&input).unwrap();
            let path = root.join(format!("input-{n}.json"));
            fs::write(&path, &bytes).unwrap();
            entries.push(json!({"entry_key":format!("entry-{n}"),"role_snapshot_digest":installed.role_snapshot_digest,"agent_configuration_digest":installed.agent_configuration_digest,"accepted_task_digest":accepted.digest().unwrap()}));
            inputs.push(json!({"entry_key":format!("entry-{n}"),"absolute_file_path":path,"content":{"byte_length":bytes.len(),"sha256":format!("sha256:{}",crate::jcs::sha256_hex(&bytes))}}));
        }
        let request = json!({"schema":"dolgorae.external-specialist-request/v5","operation":"assign_group","scope_kind":"external_engagement","scope_ref":engagement,"idempotency_key":"research-group","expected_revision":null,"manifest":{"schema":"dolgorae.group-assignment/v1","scope_kind":"external_engagement","scope_ref":engagement,"entries":entries},"inputs":inputs});
        assert!(
            crate::specialist_facade::validates(&request, "assign_group_request"),
            "group request schema: {request}"
        );
        let mut stale = request.clone();
        stale["idempotency_key"] = json!("stale-group");
        stale["expected_revision"] = json!(999);
        assert_eq!(
            research_group::assign(&f.scope(), None, &caller, &port, &stale)
                .unwrap_err()
                .code,
            "REVISION_CONFLICT"
        );
        assert!(
            port.starts.borrow().is_empty(),
            "revision fence precedes all member effects"
        );
        let assigned = research_group::with_dispatch_limit(0, || {
            research_group::assign(&f.scope(), None, &caller, &port, &request)
        })
        .unwrap();
        assert!(
            port.starts.borrow().is_empty(),
            "receipt commit is durable before the first member effect"
        );
        assert_eq!(f.task_count(), 0);
        for n in 0..2 {
            fs::remove_file(root.join(format!("input-{n}.json"))).unwrap();
        }
        assert_eq!(
            research_group::with_dispatch_limit(1, || research_group::assign(
                &f.scope(),
                None,
                &caller,
                &port,
                &request
            ))
            .unwrap(),
            assigned
        );
        assert_eq!(
            f.task_count(),
            1,
            "restart after receipt loss resumes the first captured child without its source file"
        );
        assert_eq!(
            research_group::assign(&f.scope(), None, &caller, &port, &request).unwrap(),
            assigned
        );
        assert_eq!(
            port.starts.borrow().len(),
            1,
            "compatible group entries share the provider-reserved execution Run"
        );
        assert_eq!(
            port.dispatched.borrow().len(),
            0,
            "group admission queues both entries for the existing bounded scheduler"
        );
        assert_eq!(f.task_count(), 2);
        let stored = EngagementStore::open_read_only(&f.database()).unwrap();
        let queued: i64 = stored
            .connection()
            .query_row(
                "SELECT COUNT(*) FROM tasks WHERE state='queued'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(
            queued, 2,
            "both entries retain actual accepted task identities in the queue"
        );
        drop(stored);
        assert!(
            crate::specialist_facade::validates(&assigned, "assign_group_response"),
            "{assigned}"
        );
        assert_eq!(
            research_group::assign(&f.scope(), None, &caller, &port, &request).unwrap(),
            assigned
        );
        let collect = json!({"scope_kind":"external_engagement","scope_ref":engagement,"group_ref":assigned["group_ref"]});
        let coverage = research_group::collect(&f.scope(), None, &port, &collect).unwrap();
        assert_eq!(coverage["coverage"]["sources"].as_array().unwrap().len(), 2);
        assert!(
            coverage["coverage"]["sources"]
                .as_array()
                .unwrap()
                .iter()
                .all(|row| row["worker_ref"].is_string() && row["task_ref"].is_string()),
            "authoritative coverage links both actual accepted assignments: {coverage}"
        );
        assert_eq!(
            port.dispatched.borrow().len(),
            0,
            "replay and collection dispatch no additional work"
        );
        assert!(
            crate::specialist_facade::validates(&coverage, "collect_group_response"),
            "{coverage}"
        );
        let mut changed = request.clone();
        changed["manifest"]["entries"][0]["accepted_task_digest"] =
            json!(format!("sha256:{}", "0".repeat(64)));
        assert_eq!(
            research_group::assign(&f.scope(), None, &caller, &port, &changed)
                .unwrap_err()
                .code,
            "IDEMPOTENCY_CONFLICT"
        );
        let mut wait = collect;
        wait["predicate"] = json!({"kind":"k","k":0});
        wait["timeout_seconds"] = json!(0);
        assert_eq!(
            research_group::await_group(&f.scope(), None, &port, &wait)
                .unwrap_err()
                .code,
            "GROUP_MANIFEST_INVALID"
        );
    }
    #[test]
    fn result_component_artifact_authorizes_current_owner_and_reads_exact_chunks() {
        let mut fixture = Fixture::new();
        fixture.initialize_writer_authority();
        let credential_path = fixture.root.join("component-controller.json");
        let created = crate::controller::create_controller_credential(
            &credential_path,
            ControllerKind::Automation,
            "component-test".into(),
            Some("owner".into()),
            None,
        )
        .unwrap();
        let carrier = crate::controller::CredentialCarrier::open_path(&credential_path).unwrap();
        fixture.controller =
            crate::controller::binding_from_credential(&created.credential, 1, &carrier).unwrap();
        let session = fixture.managed_session();
        let port = FakePort::new();
        let caller = caller(4);
        let member = Uuid::parse_str(
            &fixture
                .spawn_member(session, "component-spawn", &port)
                .member
                .member_ref,
        )
        .unwrap();
        let (observation, _) = fixture
            .assign(
                session,
                "component-task",
                &caller,
                &port,
                managed_assign(member, "Read the original result.\n", "read_only", None),
            )
            .unwrap();
        let task = Uuid::parse_str(&observation.task_ref).unwrap();
        fixture.publish_member_manifest(session, member);
        let child_credential_path = fixture.root.join("private-child-controller.json");
        let child_created = crate::controller::create_controller_credential(
            &child_credential_path,
            ControllerKind::Automation,
            "private-child".into(),
            Some("child".into()),
            None,
        )
        .unwrap();
        let child_carrier =
            crate::controller::CredentialCarrier::open_path(&child_credential_path).unwrap();
        let child_binding = crate::controller::binding_from_credential(
            &child_created.credential,
            1,
            &child_carrier,
        )
        .unwrap();
        let child_binding_path =
            crate::run::run_root(&fixture.state_root, member).join("controller.json");
        fs::write(
            &child_binding_path,
            serde_json::to_vec(&child_binding).unwrap(),
        )
        .unwrap();
        fs::set_permissions(&child_binding_path, fs::Permissions::from_mode(0o600)).unwrap();

        let bytes = (0..1_100_003)
            .map(|index| b'a' + (index % 26) as u8)
            .collect::<Vec<_>>();
        fixture.settle_managed_task(
            session,
            member,
            task,
            "completed",
            Some(std::str::from_utf8(&bytes).unwrap()),
        );
        let mut store = EngagementStore::open(&fixture.database()).unwrap();
        let result: crate::delegation_identity::CompleteResult = serde_json::from_slice(
            &crate::orchestration::successor_task_result(store.connection(), task)
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        let publication =
            crate::result_component_artifact::Publication::prepare(&fixture.view, member, &result)
                .unwrap();
        store
            .transact(|tx| {
                publication.retain(tx)?;
                crate::engagement::retain_checked_task_output(tx, task, b"{}", &bytes)
            })
            .unwrap();
        let public = crate::result_component_artifact::public_result(
            &fixture.state_root,
            &fixture.view,
            &result,
        )
        .unwrap();
        let artifact = public["final_response"]["artifact"]["artifact_id"]
            .as_str()
            .unwrap();
        let snapshot = crate::snapshot::RunSnapshot::load(&fixture.state_root, member, 0).unwrap();
        let before = fixture.database_bytes();
        assert_eq!(
            crate::artifact::metadata(&fixture.state_root, &snapshot, artifact, None)
                .unwrap_err()
                .code,
            "CONTROLLER_REQUIRED"
        );
        let metadata =
            crate::artifact::metadata(&fixture.state_root, &snapshot, artifact, Some(&carrier))
                .unwrap();
        assert_eq!(metadata.artifact.byte_length, bytes.len() as u64);
        assert_eq!(metadata.artifact.sha256, crate::jcs::sha256_hex(&bytes));
        let first = crate::artifact::chunk(
            &fixture.state_root,
            &snapshot,
            artifact,
            (0, 1_048_576),
            Some(&carrier),
        )
        .unwrap();
        let last = crate::artifact::chunk(
            &fixture.state_root,
            &snapshot,
            artifact,
            (1_048_576, 1_048_576),
            Some(&carrier),
        )
        .unwrap();
        assert!(!first.eof);
        assert!(last.eof);
        assert_eq!([first.data, last.data].concat(), bytes);
        assert!(
            crate::artifact::chunk(
                &fixture.state_root,
                &snapshot,
                artifact,
                (0, 1_048_577),
                Some(&carrier)
            )
            .is_err()
        );
        assert!(
            crate::result_component_artifact::read_bound(
                &fixture.state_root,
                Uuid::now_v7(),
                Uuid::parse_str(artifact).unwrap(),
                Some(&carrier)
            )
            .is_err()
        );
        assert!(
            crate::result_component_artifact::read_bound(
                &fixture.state_root,
                member,
                Uuid::now_v7(),
                Some(&carrier)
            )
            .unwrap()
            .is_none()
        );
        assert_eq!(
            fixture.database_bytes(),
            before,
            "ArtifactGet/ReadChunk leave publication and source bytes unchanged"
        );

        let digest = crate::jcs::sha256_hex(&bytes);
        store
            .connection()
            .execute(
                "UPDATE result_content SET bytes=?1 WHERE sha256=?2",
                rusqlite::params![b"corrupt source".as_slice(), &digest],
            )
            .unwrap();
        assert!(
            crate::artifact::metadata(&fixture.state_root, &snapshot, artifact, Some(&carrier))
                .is_err(),
            "content tampering never serves a chunk"
        );
        store
            .connection()
            .execute(
                "UPDATE result_content SET bytes=?1 WHERE sha256=?2",
                rusqlite::params![&bytes, &digest],
            )
            .unwrap();
        store.connection().execute("UPDATE result_content_refs SET retired_operation=?1 WHERE owner_kind='accepted_task' AND owner_id=?2 AND representation='final_response'",rusqlite::params![Uuid::now_v7().to_string(),task.to_string()]).unwrap();
        assert_eq!(
            crate::artifact::metadata(&fixture.state_root, &snapshot, artifact, Some(&carrier))
                .unwrap_err()
                .code,
            "RESULT_CONTENT_UNAVAILABLE"
        );
        store.connection().execute("UPDATE result_content_refs SET retired_operation=NULL WHERE owner_kind='accepted_task' AND owner_id=?1 AND representation='final_response'",[task.to_string()]).unwrap();
        let mut rotated = fixture.controller.clone();
        rotated.identity.generation += 1;
        rotated.capability_sha256 = "a".repeat(64);
        let current = crate::run::run_root(&fixture.state_root, session).join("controller.json");
        fs::write(&current, serde_json::to_vec(&rotated).unwrap()).unwrap();
        fs::set_permissions(&current, fs::Permissions::from_mode(0o600)).unwrap();
        assert!(
            crate::artifact::metadata(&fixture.state_root, &snapshot, artifact, Some(&carrier))
                .is_err(),
            "old aggregate credential cannot read after rotation"
        );
    }
    fn task085_group_fixture(
        managed: bool,
        settle_second: bool,
        large_output: bool,
        dispatch: bool,
        entry_count: usize,
    ) -> (
        Fixture,
        DolgoraeHome,
        crate::controller::CredentialCarrier,
        Uuid,
        FakePort,
        Value,
        crate::caller_scope::TrustedCallerScope,
    ) {
        let mut f = Fixture::new();
        let home = DolgoraeHome::from_canonical_home(f.root.clone()).unwrap();
        let state = home.workspace_root(&f.view.workspace_id);
        fs::remove_dir(&f.state_root).unwrap();
        f.view = crate::workspace::WorkspaceService::new(
            crate::workspace::SystemWorkspacePlatform,
            crate::workspace::SystemGitRunner,
            home.root().to_path_buf(),
        )
        .initialize(
            Some(&f.view.canonical_path.to_path_buf().unwrap()),
            crate::workspace::WorkspaceMode::Git,
        )
        .unwrap();
        f.state_root = state;
        f.initialize_writer_authority();
        let path = f.root.join("merge-controller.json");
        let credential = crate::controller::create_controller_credential(
            &path,
            if managed {
                ControllerKind::InteractiveClient
            } else {
                ControllerKind::Automation
            },
            "merge-test".into(),
            Some("owner".into()),
            None,
        )
        .unwrap();
        let carrier = crate::controller::CredentialCarrier::open_path(&path).unwrap();
        f.controller =
            crate::controller::binding_from_credential(&credential.credential, 1, &carrier)
                .unwrap();
        f.set_up_namespace();
        let aggregate = if managed {
            let root = Uuid::now_v7();
            let mut sessions =
                crate::orchestration::OrchestrationStore::open(&f.state_root).unwrap();
            let session = sessions
                .prepare_session(
                    &f.view.workspace_id,
                    root,
                    "merge-root-bootstrap",
                    &"b".repeat(64),
                    &managed_policy(),
                )
                .unwrap();
            let mut manifest = root_manifest(&f.view, &f.controller, root);
            manifest.control_mode = crate::domain::ControlMode::DirectInteractive;
            manifest.aggregate_binding = Some(crate::run::AggregateBinding {
                aggregate_kind: crate::domain::AggregateKind::OrchestratedSession,
                aggregate_id: root,
                operation_id: session.bootstrap_operation_id,
                member_kind: crate::run::AggregateMemberKind::Primary,
                policy_sha256: Some(session.specialist_policy_sha256),
                role_reference: None,
                role_snapshot_sha256: None,
                agent_configuration_sha256: None,
            });
            crate::run::RunStore::new(crate::workspace::SystemWorkspacePlatform, &f.state_root)
                .publish(&manifest)
                .unwrap();
            sessions.mark_primary_intent(root).unwrap();
            sessions.finish_primary_publication(root, Ok(())).unwrap();
            root
        } else {
            f.open()
        };
        let installed = f.install();
        let snapshot =
            crate::provisioning::retained_snapshot(&f.state_root, &installed.provisioning_ref)
                .unwrap();
        let (_, configuration) = snapshot.admitted_configuration().unwrap();
        let port = FakePort::new();
        let caller = caller(16);
        let mut entries = Vec::new();
        let mut inputs = Vec::new();
        for index in 0..entry_count {
            let mut task = fixture_task();
            task.expected_output = "structured_findings_v1".into();
            task.brief = format!("Research exact source {index}");
            let (accepted, _) = crate::successor_capture::capture_facade_task(
                &configuration,
                &task,
                "read_only",
                None,
            )
            .unwrap();
            let input = json!({"schema":"dolgorae.group-task-input/v1","provisioning_ref":installed.provisioning_ref,"assignment":{"task_body":task,"accepted_task_identity":accepted,"deadline_seconds":600}});
            let bytes = crate::operation::canonical(&input).unwrap();
            let path = f
                .view
                .canonical_path
                .to_path_buf()
                .unwrap()
                .join(format!("merge-input-{index}.json"));
            fs::write(&path, &bytes).unwrap();
            entries.push(json!({"entry_key":format!("entry-{index}"),"role_snapshot_digest":installed.role_snapshot_digest,"agent_configuration_digest":installed.agent_configuration_digest,"accepted_task_digest":accepted.digest().unwrap()}));
            inputs.push(json!({"entry_key":format!("entry-{index}"),"absolute_file_path":path,"content":crate::delegation_identity::BytesRef::from_bytes(&bytes)}));
        }
        let kind = if managed {
            "orchestrated_session"
        } else {
            "external_engagement"
        };
        let request = json!({"schema":"dolgorae.external-specialist-request/v5","operation":"assign_group","scope_kind":kind,"scope_ref":aggregate,"idempotency_key":"merge-sources","expected_revision":null,"manifest":{"schema":"dolgorae.group-assignment/v1","scope_kind":kind,"scope_ref":aggregate,"entries":entries},"inputs":inputs});
        let context = f.managed_context(aggregate, "merge-sources");
        let assigned =
            research_group::with_dispatch_limit(if dispatch { usize::MAX } else { 0 }, || {
                research_group::assign(
                    &f.scope(),
                    managed.then_some(&context),
                    &caller,
                    &port,
                    &request,
                )
                .unwrap()
            });
        let coverage = research_group::collect(
            &f.scope(),
            managed.then_some(&context),
            &port,
            &json!({"scope_kind":kind,"scope_ref":aggregate,"group_ref":assigned["group_ref"]}),
        )
        .unwrap();
        let rows = coverage["coverage"]["sources"].as_array().unwrap();
        let mut published = std::collections::BTreeSet::new();
        for (index, row) in rows.iter().enumerate() {
            if !dispatch {
                continue;
            }
            let member = Uuid::parse_str(row["worker_ref"].as_str().unwrap()).unwrap();
            if published.insert(member) {
                if managed {
                    let connection = Connection::open(f.database()).unwrap();
                    let facts =
                        crate::orchestration::successor_member(&connection, aggregate, member)
                            .unwrap()
                            .unwrap();
                    let controller: String = connection
                        .query_row(
                            "SELECT controller_binding_json FROM brokered_members WHERE run_id=?1",
                            [member.to_string()],
                            |row| row.get(0),
                        )
                        .unwrap();
                    let controller = serde_json::from_str(&controller).unwrap();
                    let manifest = member_manifest(
                        &f.view,
                        &controller,
                        member,
                        aggregate,
                        facts.spawn_operation_id,
                        &snapshot,
                    );
                    crate::run::RunStore::new(
                        crate::workspace::SystemWorkspacePlatform,
                        &f.state_root,
                    )
                    .publish(&manifest)
                    .unwrap();
                } else {
                    f.publish_external_member_manifest(aggregate, member);
                }
            }
            if index == 0 || settle_second {
                if large_output {
                    let mut body: Value = serde_json::from_str(include_str!(
                        "../docs/protocol/examples/v014-identity-findings.valid.json"
                    ))
                    .unwrap();
                    let template = body["findings"][0].clone();
                    body["findings"] = json!(
                        (0..64)
                            .map(|index| {
                                let mut finding = template.clone();
                                finding["finding_key"] = json!(format!("large-{index:02}"));
                                finding["claim"] = json!("x".repeat(8192));
                                finding["limitations"] = json!(vec!["l".repeat(4096); 32]);
                                finding
                            })
                            .collect::<Vec<_>>()
                    );
                    task085_publish_value(&f, managed, aggregate, row, &body);
                } else {
                    task085_publish_findings(&f, managed, aggregate, row);
                }
            }
        }
        for input in request["inputs"].as_array().unwrap() {
            fs::remove_file(input["absolute_file_path"].as_str().unwrap()).unwrap();
        }
        let coverage = research_group::collect(
            &f.scope(),
            managed.then_some(&context),
            &port,
            &json!({"scope_kind":kind,"scope_ref":aggregate,"group_ref":assigned["group_ref"]}),
        )
        .unwrap();
        let request = json!({"schema":"dolgorae.external-specialist-request/v5","operation":"merge_group_results","scope_kind":kind,"scope_ref":aggregate,"group_ref":assigned["group_ref"],"group_assignment_digest":assigned["manifest_digest"],"sources":coverage["coverage"]["sources"],"algorithm":"merge-exact-findings-v1","idempotency_key":"merge-key","expected_revision":null});
        (f, home, carrier, aggregate, port, request, caller)
    }
    fn task085_publish_findings(f: &Fixture, managed: bool, aggregate: Uuid, row: &Value) {
        let body: Value = serde_json::from_str(include_str!(
            "../docs/protocol/examples/v014-identity-findings.valid.json"
        ))
        .unwrap();
        task085_publish_value(f, managed, aggregate, row, &body);
    }
    fn task085_publish_value(
        f: &Fixture,
        managed: bool,
        aggregate: Uuid,
        row: &Value,
        body: &Value,
    ) {
        task085_publish_terminal(f, managed, aggregate, row, body, "completed");
    }
    fn task085_publish_terminal(
        f: &Fixture,
        managed: bool,
        aggregate: Uuid,
        row: &Value,
        body: &Value,
        outcome: &str,
    ) {
        let terminal = if outcome == "unavailable" {
            "failed"
        } else {
            outcome
        };
        let state = if terminal == "completed" {
            "completed_not_delivered"
        } else {
            terminal
        };
        let failure = match outcome {
            "completed" => None,
            "failed" => Some("FINDINGS_OUTPUT_INVALID"),
            "cancelled" => Some("CANCELLED"),
            "expired" => Some("OPERATION_TIMEOUT"),
            "unavailable" => Some("COMPLETE_RESULT_UNAVAILABLE"),
            _ => panic!("unexpected fixture terminal"),
        };
        let member = Uuid::parse_str(row["worker_ref"].as_str().unwrap()).unwrap();
        let task = Uuid::parse_str(row["task_ref"].as_str().unwrap()).unwrap();
        let mut store = EngagementStore::open(&f.database()).unwrap();
        let accepted = if managed {
            crate::successor_capture::retained_accepted_task(
                &crate::orchestration::successor_task(store.connection(), aggregate, task)
                    .unwrap()
                    .unwrap()
                    .accepted_request_json,
            )
            .unwrap()
        } else {
            store
                .external_task_identity(aggregate, task)
                .unwrap()
                .unwrap()
        };

        let bytes = crate::operation::canonical(body).unwrap();
        let result = crate::delegation_identity::CompleteResult {
            schema: crate::delegation_identity::COMPLETE_RESULT_SCHEMA.into(),
            source: crate::delegation_identity::ResultSource {
                scope_kind: if managed {
                    "orchestrated_session"
                } else {
                    "external_engagement"
                }
                .into(),
                scope_ref: aggregate.to_string(),
                worker_ref: member.to_string(),
                task_ref: task.to_string(),
                role_snapshot_digest: accepted.role_snapshot_digest.clone(),
                agent_configuration_digest: accepted.agent_configuration_digest.clone(),
                accepted_task_digest: accepted.digest().unwrap(),
            },
            terminal_outcome: terminal.into(),
            final_response: Some(crate::delegation_identity::BytesRef::from_bytes(&bytes)),
            structured_output_schema: (accepted.expected_output_schema == "structured_findings_v1")
                .then(|| "structured_findings_v1".into()),
            structured_output: (accepted.expected_output_schema == "structured_findings_v1")
                .then(|| crate::delegation_identity::BytesRef::from_bytes(&bytes)),
            changes: vec![],
            attachments: vec![],
            safe_failure_code: failure.map(str::to_owned),
        };
        let canonical = if outcome == "unavailable" {
            crate::operation::canonical(&json!({"schema":"dolgorae.complete-result-unavailable/v1","reason":"complete_result_unavailable","task_ref":task})).unwrap()
        } else {
            crate::operation::canonical(&json!(result)).unwrap()
        };
        let digest = crate::jcs::sha256_hex(&canonical);
        let publication = (outcome != "unavailable").then(|| {
            crate::result_component_artifact::Publication::prepare(&f.view, member, &result)
                .unwrap()
        });
        store
            .transact(|tx| {
                crate::engagement::retain_checked_task_output(tx, task, &bytes, &bytes)?;
                if managed {
                    tx.execute(
                        "UPDATE brokered_tasks SET state='running' WHERE task_id=?1",
                        [task.to_string()],
                    )
                    .unwrap();
                    crate::orchestration::retain_successor_task_result(tx, task, &canonical)?;
                    assert!(crate::orchestration::settle_successor_task_result(
                        tx,
                        aggregate,
                        task,
                        state,
                        failure,
                        Some(&digest),
                        now_ms()?
                    )?);
                } else {
                    tx.execute(
                        "UPDATE tasks SET state='running' WHERE task_id=?1",
                        [task.to_string()],
                    )
                    .unwrap();
                    let artifact = crate::engagement::retain_task_result(
                        tx, aggregate, task, &canonical, &digest,
                    )?;
                    crate::engagement::terminalize_external_task_in(
                        tx,
                        crate::engagement::TaskTerminal {
                            engagement_id: aggregate,
                            task_id: task,
                            state,
                            safe_error_code: failure,
                            result_sha256: Some(&digest),
                            artifact_id: Some(artifact),
                            diagnostic_json: None,
                            now_ms: now_ms()?,
                        },
                    )?;
                }
                if let Some(publication) = &publication {
                    publication.retain(tx)?;
                }
                crate::caller_scope::accepted(tx, task)?;
                Ok(())
            })
            .unwrap();
    }
    #[test]
    fn task085_merge_uses_actual_sources_artifacts_and_frozen_key_recovery() {
        for managed in [false, true] {
            let (f, _home, carrier, aggregate, port, request, _caller) =
                task085_group_fixture(managed, false, false, true, 2);
            let before = port.dispatched.borrow().len();
            let merged = research_merge::merge(&f.scope(), None, &port, &request, true).unwrap();
            assert!(crate::specialist_facade::validates(
                &merged,
                "merge_group_results_response"
            ));
            let merge = Uuid::parse_str(
                merged["receipt"]["accepted_subjects"]["merge_ref"]
                    .as_str()
                    .unwrap(),
            )
            .unwrap();
            let store = EngagementStore::open_read_only(&f.database()).unwrap();
            let publication = research_merge::record(&store, merge).unwrap();
            let artifact = Uuid::parse_str(publication["artifact_id"].as_str().unwrap()).unwrap();
            let owner = Uuid::parse_str(publication["owner_run"].as_str().unwrap()).unwrap();
            assert!(
                crate::run::RunStore::new(crate::workspace::SystemWorkspacePlatform, &f.state_root)
                    .load_manifest(owner)
                    .is_ok()
            );
            let snapshot = crate::snapshot::RunSnapshot::load(&f.state_root, owner, 0).unwrap();
            assert_eq!(
                crate::artifact::metadata(&f.state_root, &snapshot, &artifact.to_string(), None)
                    .unwrap_err()
                    .code,
                "CONTROLLER_REQUIRED"
            );
            let foreign_path = f.root.join("foreign-merge-controller.json");
            crate::controller::create_controller_credential(
                &foreign_path,
                ControllerKind::Automation,
                "foreign-merge-reader".into(),
                None,
                None,
            )
            .unwrap();
            let foreign = crate::controller::CredentialCarrier::open_path(&foreign_path).unwrap();
            assert!(
                crate::artifact::metadata(
                    &f.state_root,
                    &snapshot,
                    &artifact.to_string(),
                    Some(&foreign)
                )
                .is_err()
            );
            let data = crate::artifact::chunk(
                &f.state_root,
                &snapshot,
                &artifact.to_string(),
                (0, 1_048_576),
                Some(&carrier),
            )
            .unwrap();
            assert_eq!(
                crate::delegation_identity::BytesRef::from_bytes(&data.data),
                serde_json::from_value(merged["merged_identity"]["merged_output"].clone()).unwrap()
            );
            let bytes_before = research_merge::logical_bytes(&f.state_root, owner).unwrap();
            let mut permuted = request.clone();
            permuted["sources"].as_array_mut().unwrap().reverse();
            assert_eq!(
                research_merge::merge(&f.scope(), None, &port, &permuted, true).unwrap(),
                merged
            );
            let second = request["sources"][1].clone();
            task085_publish_findings(&f, managed, aggregate, &second);
            assert_eq!(
                research_merge::merge(&f.scope(), None, &port, &request, true).unwrap(),
                merged,
                "original key freezes its original unknown source"
            );
            assert_eq!(
                research_merge::logical_bytes(&f.state_root, owner).unwrap(),
                bytes_before
            );
            let mut stale = request.clone();
            stale["idempotency_key"] = json!("new-key-old-snapshot");
            assert_eq!(
                research_merge::merge(&f.scope(), None, &port, &stale, true)
                    .unwrap_err()
                    .code,
                "REVISION_CONFLICT"
            );
            let mut conflict = request.clone();
            conflict["sources"][0]["state"] = json!("failed");
            conflict["sources"][0]["safe_failure_code"] = json!("CHANGED");
            assert_eq!(
                research_merge::merge(&f.scope(), None, &port, &conflict, true)
                    .unwrap_err()
                    .code,
                "IDEMPOTENCY_CONFLICT"
            );
            assert_eq!(
                port.dispatched.borrow().len(),
                before,
                "merge never calls the execution port"
            );
        }
    }
